const CHAPTERS: VizChapter[] = [{"id":"spring-ch01","subj":"spring","title":"Spring 核心：IoC 容器与依赖注入","summary":"IoC/DI 反转了什么；BeanFactory 与 ApplicationContext 的差异；构造器/Setter/字段注入的取舍（循环依赖与不可变性）；@Component/@Bean/@Configuration 与组件扫描；容器…","concepts":[{"id":"spring-ch01/01-ioc-basics","file":"01-ioc-basics.md","title":"一、IoC 基础与容器定位","kind":"flow","secs":[{"h":"一、什么是 IoC / 控制反转","s":"（中立陈述）IoC（Inversion of Control，控制反转）是一种设计原则：传统程序里对象自己用 new","c":null},{"h":"二、BeanFactory 与 ApplicationContext 的差异","s":"（中立陈述）BeanFactory 是最基础的容器接口，提供 getBean 等核心能力，懒加载（首次","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"java","code":"import java.util.*;\n\npublic class Ex01 {\n    static class Container {\n        private final Map<String, Object> beans = new HashMap<>();\n        public void register(String name, Object bean) { beans.put(name, bean); }\n        public Object get(String name) { return beans.get(name); }\n    }\n    static class Service { String hello() { return \"hello from service\"; } }\n…"}}]},{"id":"spring-ch01/02-di-modes","file":"02-di-modes.md","title":"二、依赖注入的三种方式","kind":"compare","secs":[{"h":"一、构造器注入 vs Setter 注入 vs 字段注入","s":"（中立陈述）Spring 支持三种注入点：构造器注入（通过构造参数）、Setter 注入（通过","c":null},{"h":"二、依赖解析：按类型与按名称（@Qualifier）","s":"（中立陈述）容器注入时先按类型（byType）在 beanDefinitionMap 中找候选。若同类型只有一个","c":null}]},{"id":"spring-ch01/03-component-scan-config","file":"03-component-scan-config.md","title":"三、组件扫描与 Java 配置","kind":"flow","secs":[{"h":"一、组件扫描与 stereotype 注解","s":"（中立陈述）@Component 及其语义化派生 @Service / @Repository / @Controller /","c":null},{"h":"二、@Bean 与 @Configuration（Java 配置 / 工厂方法）","s":"（中立陈述）@Bean 标注在方法上，方法的返回值被注册为容器中的一个 bean（即「工厂方法」）。","c":null}]},{"id":"spring-ch01/04-circular-dependency","file":"04-circular-dependency.md","title":"四、循环依赖与三级缓存","kind":"flow","secs":[{"h":"一、单例循环依赖与三级缓存","s":"（中立陈述）单例 + Setter/字段注入的循环依赖（A 依赖 B，B 依赖 A）可以被 Spring 解决，核心是一套","c":null},{"h":"二、prototype 循环依赖为何必然失败","s":"（中立陈述）prototype 作用域的 bean 每次 getBean 都新建，容器不缓存成品也不缓存早期引用","c":null}]},{"id":"spring-ch01/05-ioc-basics-practical-recipes","file":"05-ioc-basics-practical-recipes.md","title":"§5 spring-ch01 实战手记：凯喵带你把 IoC/DI 用「懵」","kind":"flow","secs":[{"h":"现场一：同类型多 Bean 时靠字段名「猜」实现","s":"凯喵 @Autowired private UserService userService;，存在两个 UserService 实现时，Spring 退化成按字段名匹配 Bean 名，改个字段名就换了实现，不报错、行为静默变。正确做法：…","c":{"lang":"java","code":"@Autowired @Qualifier(\"wechatUserService\")   // ✅ 显式指定\nprivate UserService svc;\n// 或\n@Primary                                    // 标一个默认实现\n@Component class DbUserService implements UserService {}"}},{"h":"现场二：忘了 @ComponentScan，一个 Bean 都没注册","s":"凯喵新建的 @Service 注入是 null，启动不报错运行 NPE。主类 @SpringBootApplication 只扫自己所在包及其子包，新模块在别的顶层包就被漏。要么挪包，要么显式 @ComponentScan(\"com.x…","c":{"lang":"java","code":"@SpringBootApplication\n@ComponentScan(\"com.x\")   // ✅ 扩大扫描范围\npublic class App {}"}},{"h":"现场三：构造器注入 vs setter 注入选型乱","s":"凯喵所有依赖都用字段注入，结果必填依赖没传也能启动，运行时才 NPE。规则：必填、不可变的依赖用构造器注入（启动即校验、利于测试）；可选/可变的用 setter。字段注入不利于测试和不可变，尽量少用。","c":{"lang":"java","code":"// ✅ 必填依赖用构造器注入，启动即校验\n@Service\npublic class OrderService {\n    private final PaymentClient client;\n    public OrderService(PaymentClient client) { this.client = client; }\n}"}},{"h":"现场四：构造器循环依赖，启动直接抛异常","s":"凯喵把 A、B 都用构造器互相注入，启动报 BeanCurrentlyInCreationException。Spring 解不了构造器级别的循环（实例化就要对方，对方还没出生）。至少一方改字段/setter 注入，或拆出第三方依赖。","c":{"lang":"java","code":"@Component\npublic class A { @Autowired private B b; }   // ✅ 至少一方非构造器注入\n@Component\npublic class B { @Autowired private A a; }"}},{"h":"现场五：@Autowired required 默认 true，缺 Bean 即失败","s":"凯喵 @Autowired private Optional<Feature> f; 想表达「有就有没有拉倒」，旧版却因 required 默认 true 启动失败。Spring 4.3+ 对构造器参数支持 Optional/@Null…","c":{"lang":"java","code":"// ✅ 可选依赖用 Optional，缺失不报错\npublic MyService(Optional<Cache> cache) { this.cache = cache; }"}},{"h":"现场六：@Value 取不到配置，原因是占位符 or 类型","s":"凯喵 @Value(\"${app.timeout}\") 拿到 null，因为根本没在 application.yml 配这个 key，或类型不对（字符串塞进 int）。用 : 给默认值防缺失，复杂配置用 @ConfigurationPr…","c":{"lang":"java","code":"@Value(\"${app.timeout:3000}\")            // ✅ 缺失用默认值 3000\nprivate int timeout;\n// 或批量绑定\n@ConfigurationProperties(\"app\") class AppProps { int timeout; }"}},{"h":"现场七：Bean 不是线程安全，singleton 里存状态","s":"凯喵在 singleton @Service 存了「当前用户」字段，并发请求互相串号。singleton 默认无状态共享，存可变成员即线程不安全。请求级数据走方法参数或 RequestContextHolder，或 @Scope(\"re…","c":{"lang":"java","code":"// ❌ singleton 存请求状态\nprivate String currentUser;\n// ✅ 方法参数传递\npublic void handle(String currentUser) { ... }"}},{"h":"现场八：@Lazy 误用掩盖循环依赖","s":"凯喵用 @Lazy 把启动时的循环依赖报错压到首次请求才炸，更难定位。@Lazy 是解耦手段不是创可贴，优先重构依赖方向而非一路 @Lazy。","c":{"lang":"java","code":"@Autowired @Lazy private HeavyService s;  // 仅当确实想延迟创建，而非藏循环"}},{"h":"现场九：@PostConstruct 里依赖还没就绪的 Bean","s":"凯喵在 @PostConstruct 用另一个 Bean，偶发 NPE——初始化顺序不保证按你写的来。依赖谁就显式注入谁，别假设它先好；需要「全部就绪后」动作放 ApplicationRunner / SmartInitializing…","c":{"lang":"java","code":"@PostConstruct\nvoid init() { this.cfg = load(this.config.getPath()); }  // config 已注入则安全"}},{"h":"现场十：用 new 创建 Bean，@Autowired 全失效","s":"凯喵 new UserService() 自己 new 对象，结果里面的 @Autowired 字段全是 null——Spring 只管理它自己创建的 Bean，你手动 new 的容器不碰。要用容器里的依赖必须让容器创建（注入或 get…","c":{"lang":"java","code":"// ❌ new 出来的对象不走容器，依赖为 null\nUserService s = new UserService();\n// ✅ 交给容器\n@Autowired UserService s;"}},{"h":"现场十一：原型 Bean 被 singleton 持有，没真正多例","s":"凯喵给 Bean 标 @Scope(\"prototype\") 又 @Autowired 进 singleton，容器只在注入时 new 一次。prototype 的「每次新实例」只对直接 getBean / ObjectProvider…","c":{"lang":"java","code":"@Autowired ObjectProvider<Task> taskProvider;  // ✅ 每次 getObject 新实例"}},{"h":"现场十二：条件化 Bean 没生效，@Profile 拼错","s":"凯喵写 @Profile(\"prod\") 的 Bean 在 dev 也加载，因为 --spring.profiles.active 没传或拼错成 pro。条件化 Bean 依赖激活的环境，先用 Environment 打印确认当前 pr…","c":{"lang":"bash","code":"--spring.profiles.active=prod   # 确认激活的 profile 正确"}},{"h":"现场之外：凯喵的注入三原则","s":"刚上手 Spring，凯喵定下三个原则避免踩坑。第一，依赖从哪来就由谁来管：容器创建的 Bean 才能享受自动装配，自己 new 的对象里的 @Autowired 永远是 null，这个铁律记住能省下无数 NPE。第二，必填依赖用构造器…","c":null},{"h":"现场拾遗：从看报错到看容器","s":"再补一句：遇到 Bean 相关的问题，别急着改代码，先看容器的启动日志和 Bean 定义。Spring 启动时打印的 Bean 名、创建顺序、注入来源，基本能把「为啥是 null」「为啥注入了错的实现」讲得明明白白。养成「先看容器、再改…","c":null},{"h":"一句话收尾","s":"凯喵最后提醒：IoC 不是魔法，它只是把「对象怎么造、怎么连」这件事从你手里收归容器统一管。你写的还是普通类和普通方法，只不过创建和装配的时机交了出去。想明白这一点，那些「为什么注入是 null」「为什么顺序不对」的问题，都会变成「对象…","c":null},{"h":"🧑‍💻 程序员视角","s":"同类型有多个 Bean 时，Spring 先按类型找、再按字段名匹配——字段名恰好等于某个 Bean 名就「碰巧」注入了，改个字段名立刻启动失败。@ComponentScan 漏配是「Bean 找不到」的头号原因：默认只扫启动类所在包及…","c":null},{"h":"🎓 博士生视角","s":"IoC 容器的本质是「对象图的生命周期管理 + 依赖解析」：BeanDefinition 描述如何创建，BeanFactory 负责实例化与注入，ApplicationContext 在其上叠加事件、国际化、资源加载等企业级能力。三级缓…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"IoC 与 DI 的关系","stem":"下列关于 IoC（控制反转）与 DI（依赖注入）的说法，正确的是？","opts":[{"k":"A","t":"IoC 是依赖注入的一种具体实现"},{"k":"B","t":"DI 是 IoC 最常用的实现手段，容器把依赖注入对象"},{"k":"C","t":"IoC 等同于工厂模式"},{"k":"D","t":"DI 与 IoC 是完全无关的两个概念"}],"ans":"B","why":"IoC 是设计原则（把创建/装配控制权交给容器），DI 是实现手段；工厂模式只是 IoC 的载体之一，不能等同。"},{"kind":"fix_error","q":"修复字段注入导致的单测不可测","stem":"下面代码用字段注入，单测无法传入 mock。请改为构造器注入（依赖可声明为 final）。 java @Service public class OrderService { @Autowired private PaymentClient client; public String pay(String id){ return client.charge(id); } }","opts":[],"ans":"@Service public class OrderService { private final PaymentClient client; public OrderService(PaymentClient client) { this.client = client; } public String pay(S…","why":"构造器注入让依赖为 final、对象不可变且单测可直接 new OrderService(mock) 传入，可测试性大幅提升。"},{"kind":"output","q":"判断单例共享状态输出","stem":"容器注册 Counter 为单例。下列代码输出什么？ java Counter a = ctx.getBean(Counter.class); Counter b = ctx.getBean(Counter.class); a.n = 10; System.out.println(a == b); System.out.println(b.n);","opts":[],"ans":"true 10","why":"单例作用域下 getBean 返回同一实例，a、b 指向同一对象，对 a 的修改在 b 上可见。"},{"kind":"coding","q":"课程表（依赖图环检测，与 DI 循环依赖同构）","stem":"给定课程先修依赖 prerequisites，判断能否完成所有课程。等价于检测有向图是否存在环——与「Spring 单例循环依赖能否被三级缓存解决」是同一建模。","opts":[],"ans":"拓扑排序（Kahn 或 DFS 三色标记）检测有向图环","why":"把依赖建成有向图，能拓扑排序则无环（可完成）；有环则无法完成，类比 prototype 循环依赖必然失败。"},{"kind":"coding","q":"从零实现迷你 IoC 容器（反射 + 三级缓存）","stem":"参考 Spring 思路，用纯 JDK 实现一个迷你容器：支持 @Component 扫描、@Autowired 字段反射注入、单例缓存，并尝试用三级缓存解决单例循环依赖。","opts":[],"ans":"见参考仓库的最小实现思路","why":"综合考察 BeanDefinition 注册表、反射填充、早期引用暴露与缓存层级，是本章知识的工程落地。"},{"kind":"choice","q":"BeanFactory 与 ApplicationContext 差异","stem":"关于 BeanFactory 与 ApplicationContext，下列说法准确的是？","opts":[{"k":"A","t":"ApplicationContext 运行期获取单例比 BeanFactory 快"},{"k":"B","t":"ApplicationContext 继承 BeanFactory，并在启动期预实例化单例，额外提供国际化/事件/AOP…"},{"k":"C","t":"BeanFactory 也默认提供 ApplicationEvent 事件发布"},{"k":"D","t":"两者没有任何关系，是独立的两套容器"}],"ans":"B","why":"ApplicationContext 是 BeanFactory 的超集，预实例化单例（fail-fast）、提供国际化/事件/AOP；运行期单例获取两者都是 Map 查找，无快慢之分。"}],"works":[{"h":"字段注入破坏可测试性","d":"把 @Autowired 写在私有字段上，单测无法像构造器那样直接传入 mock，必须启动容器或反射注入。正确写法：强制依赖改用构造器注入，private final Repo repo; 并在构造器上 @Autowired（单构造器时可省略）。"},{"h":"扫不到 bean（包不在扫描根包下）","d":"业务类放在启动类上层/平行包，默认 @ComponentScan 扫不到，运行期 NPE。正确写法：把启动类放在最外层根包，或用 @ComponentScan(\"com.xxx\") 显式指定基础包。"},{"h":"构造器循环依赖启动即崩","d":"A、B 互相用构造器注入，三级缓存救不了，抛 BeanCurrentlyInCreationException。正确写法：重构拆解依赖（抽接口/搬逻辑），或在一方加 @Lazy 延迟注入打破环。"},{"h":"@Component 里的 @Bean 方法互调产生多例","d":"配置类只标了 @Component 而非 @Configuration，类内 @Bean 互调是普通方法调用，每次新建，单例变多例。正确写法：装配 bean 的配置类标 @Configuration，让 CGLIB 增强保证单例共享。"},{"h":"同类型多 bean 未加 @Qualifier 抛歧义","d":"一个接口两个实现都进容器，注入时 NoUniqueBeanDefinitionException。正确写法：用 @Qualifier(\"name\") 精确点名，或在默认实现上标 @Primary。"},{"h":"prototype + 互相注入必然失败","d":"prototype 每次新建且不缓存早期引用，循环依赖直接 BeanCurrentlyInCreationException，没有任何缓存能救。正确写法：改为单例协作，或抽一个被双方依赖的第三方 bean。"},{"h":"误以为 ApplicationContext 比 BeanFactory「运行更快」","d":"二者单例获取都是 Map 查找，差异只在启动期是否预实例化；ApplicationContext 启动更慢但 fail-fast、运行期无差别。正确写法：按「是否需要国际化/事件/AOP/更早暴露装配错误」选 ApplicationContext，不要以性能为由选 BeanFactory。"},{"h":"字段注入 @Autowired 让类无法脱离容器测试","d":"字段注入的对象只能靠反射塞进去，单元测试要么起半个 Spring 上下文（慢），要么用 ReflectionTestUtils（脆）。字段还不能 final，等于放弃了「依赖不可变」。 构造器注入（只有一个构造器时可省注解）；字段声明 final，依赖缺失在编译/启动期就暴露。"}],"asks":[{"q":"Spring 是怎么解决循环依赖的？为什么用三级缓存而不是两级？","a":"Spring 用三级缓存解决单例 + Setter/字段注入的循环依赖： - 一级 singletonObjects：成品单例； - 二级 earlySingletonObjects：早期暴露的半成品引用； - 三级 singletonFactories：能产出早期引用的 ObjectFactory。 流程：实例化 A（仅 new）→ 把 A 的早期引用工厂放进三级缓存 → 填充 A 需要 B →…","fu":["构造器注入的循环依赖为什么救不了？","prototype 作用域的循环依赖能解决吗？为什么？"],"tag":"通用/字节"},{"q":"构造器注入、Setter 注入、字段注入你怎么选？","a":"强制/必填依赖用构造器注入：依赖可声明为 final，对象构造即完整、不可变、线程安全，且单测可直接传 mock，循环依赖会早失败。 可选依赖用 Setter 注入：允许构造后变更。 字段注入（@Autowired 标字段）不推荐：写在私有字段上，单测必须起容器或反射才能注入，且无法声明 final，可测试性与不可变性最差。 结论：Spring 官方推荐「构造器注入为主，Setter 为辅」。","fu":["字段注入到底有什么具体危害？","为什么字段注入的循环依赖能被悄悄解决，反而更危险？"],"tag":"通用/腾讯"},{"q":"BeanFactory 和 ApplicationContext 有什么区别？","a":"三点： 1. 继承关系：ApplicationContext 是 BeanFactory 的超集（继承并扩展多个子接口）。 2. 实例化时机：BeanFactory 懒加载（首次 getBean 才创建）；ApplicationContext 在 refresh() 时预实例化所有非懒加载单例（fail-fast，更早暴露装配错误）。 3. 能力边界：ApplicationContext 额外提供…","fu":["为什么生产几乎都用 ApplicationContext？","XmlBeanFactory 现在还能用吗？"],"tag":"通用/京东"},{"q":"一个接口有两个实现，怎么注入指定的那个？","a":"byType 找到多个候选时，需要 tie-breaker： - @Qualifier(\"name\")：按 bean 名称精确指定（优先级最高）； - @Primary：在默认实现上标，作为多候选时的首选； - 字段名兜底：注入点字段名等于目标 bean 名时按 byName 命中。 若都不指定会抛 NoUniqueBeanDefinitionException。注意 @Qualifier 是按名…","fu":["@Primary 和 @Qualifier 谁优先级高？","为什么同类型多 bean 不指定会抛异常？"],"tag":"通用/拼多多"}]},{"id":"spring-ch02","subj":"spring","title":"Bean 生命周期与作用域","summary":"实例化→属性填充→Aware 回调→BeanPostProcessor 前置→@PostConstruct→初始化方法→后置处理→使用→销毁；singleton/prototype/request/session 的语义差异与 protot…","concepts":[{"id":"spring-ch02/01-lifecycle","file":"01-lifecycle.md","title":"一、Bean 生命周期：从定义到销毁","kind":"timeline","secs":[{"h":"一、完整生命周期阶段（中立陈述）","s":"Spring 单例 Bean 在 ApplicationContext 启动时（或首次 getBean 时，懒加载）经历一条确定性流水线：","c":null},{"h":"二、初始化与销毁的三种方式及顺序（中立陈述）","s":"Spring 提供两套各三种等价钩子：","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"java","code":"import java.util.*;\n\npublic class Main {\n    static class BeanDefinition {\n        String beanName;\n        String className;\n        String scope = \"singleton\";\n        BeanDefinition(String n, String c) { beanName = n; className = c; }\n    }\n…"}}]},{"id":"spring-ch02/02-scope","file":"02-scope.md","title":"二、Bean 作用域：singleton / prototype / request / session","kind":"flow","secs":[{"h":"一、四种作用域的语义差异（中立陈述）","s":"Spring 通过 scope 决定 getBean 时返回的是「同一实例」还是「新实例」：","c":null},{"h":"二、prototype 注入 singleton 的陷阱（中立陈述）","s":"当单例 bean 依赖 prototype bean 时，容器只在「创建单例」那一刻注入一次 prototype 实例；此后单例长期持有这同一个 prototype 引用，后续 getBean 不会重新注入。于是「想每次用新 proto…","c":null}]},{"id":"spring-ch02/03-postprocessor-aware","file":"03-postprocessor-aware.md","title":"三、BeanPostProcessor 与 Aware 回调","kind":"flow","secs":[{"h":"一、BeanPostProcessor 原理与执行时机（中立陈述）","s":"BeanPostProcessor（BPP）是 Spring 的容器级 bean 拦截器：在「每个 bean 实例化、属性填充之后」统一执行，提供两个钩子：","c":null},{"h":"二、Aware 回调体系（中立陈述）","s":"Aware 是一族「让 bean 感知容器基础设施」的标记接口，命名即 XxxAware + setXxx(...)：","c":null}]},{"id":"spring-ch02/04-circular-dependency-cglib","file":"04-circular-dependency-cglib.md","title":"四、循环依赖、三级缓存与 @Configuration 代理","kind":"flow","secs":[{"h":"一、循环依赖与三级缓存（中立陈述）","s":"流程：实例化 A → 把「A 的早期引用工厂」放进三级缓存 → 填充 A 需要 B → 创建 B（同样暴露） → 填充 B 需要 A → 从三级缓存取 A 的早期引用（升到二级）注入 B → B 完成进一级 → 回到 A 注入成品 B…","c":null},{"h":"二、@Configuration 的 CGLIB 代理保证单例（中立陈述）","s":"@Configuration 标注的配置类在容器里被增强：Spring 用 CGLIB 生成它的子类（AppConfig$$SpringCGLIB），重写每个 @Bean 方法，方法体变成「先去容器单例缓存查，命中就返回，未命中才调父类…","c":null}]},{"id":"spring-ch02/05-ioc-practical-recipes","file":"05-ioc-practical-recipes.md","title":"§5 spring-ch02 实战手记：凯喵带你把 IoC 容器用「炸」","kind":"flow","secs":[{"h":"现场一：构造器注入循环依赖，容器直接抛 BeanCurrentlyInCreationExc…","s":"凯喵把 A、B 都用构造器互相注入，启动即报错。Spring 解决不了构造器循环的依赖（实例化时就要对方，但对方还没出生）。解法：至少一方改用字段/setter 注入，或拆出第三方依赖。","c":{"lang":"java","code":"@Component\npublic class A {\n    // ❌ 构造器循环，容器无解\n    // public A(B b) { this.b = b; }\n    @Autowired private B b;   // ✅ 改成字段/setter 注入\n}"}},{"h":"现场二：prototype 注入 singleton，每次拿到的还是同一个","s":"凯喵把 prototype 的 Bean 用 @Autowired 注进 singleton，满心以为每次是新实例，结果一直是一个。singleton 只初始化一次，注入时就把 prototype 的固定引用存进去了。想每次拿新实例要用…","c":{"lang":"java","code":"@Autowired ObjectProvider<Task> taskProvider;   // ✅ 每次 get 一个新 prototype\nvoid run() { Task t = taskProvider.getObject(); }"}},{"h":"现场三：忘了加 @ComponentScan，一个 Bean 都没注册","s":"凯喵新建的 @Service 死活注入为 null，启动不报错但运行 NPE。根因：主类上的 @SpringBootApplication 只扫描自己所在包及其子包，新模块放在别的顶层包就被漏掉。要么挪包，要么显式 @Component…","c":{"lang":"java","code":"@SpringBootApplication\n@ComponentScan(\"com.x\")   // ✅ 显式扩大扫描范围\npublic class App { public static void main(String[] a){ SpringApplication.run(App.class,a);} }"}},{"h":"现场四：@Lazy 误用，掩盖了真正的循环依赖","s":"凯喵用 @Lazy 把启动时的循环依赖报错压下去，以为修好了，结果首次请求时才懒加载、那时才炸，且更难定位。@Lazy 是解耦手段不是创可贴，优先重构依赖方向而非一路 @Lazy。","c":{"lang":"java","code":"@Autowired @Lazy private HeavyService s;  // 仅当确实想延迟创建；别用来藏循环依赖"}},{"h":"现场五：@PostConstruct / InitializingBean 顺序搞混","s":"凯喵在 @PostConstruct 里依赖另一个还没初始化的 Bean，偶发 NPE。Bean 初始化顺序由依赖决定，不保证和你写的顺序一致。依赖某个 Bean 就显式注入它，别假设它先好。","c":{"lang":"java","code":"@PostConstruct\nvoid init() {\n    // ✅ 依赖的 bean 通过字段注入进来，保证已就绪\n    this.cache = buildCache(config.getSize());\n}"}},{"h":"现场六：Bean 不是线程安全，singleton 里存了请求级状态","s":"凯喵在 singleton 的 @Service 里存了个 Map 记录「当前用户」，并发请求互相串号。singleton Bean 默认无状态共享，存可变成员就是线程不安全。请求级数据走方法参数或 RequestContextHold…","c":{"lang":"java","code":"// ❌ singleton 里存请求状态\nprivate Map<String,Object> ctx;\n// ✅ 用方法参数传递，或 @Scope(\"request\")\npublic void handle(User u) { Map<String,Object> ctx = new HashMap<>(); ... }"}},{"h":"现场七：@Scope(\"prototype\") 但被 singleton 持有，没真正多例","s":"凯喵给 Bean 标了 @Scope(\"prototype\")，却又把它 @Autowired 进 singleton，结果容器只在注入那一刻 new 一次。prototype 的「每次请求新实例」只对直接 getBean 或 Obje…","c":{"lang":"java","code":"@Autowired ObjectProvider<LogEntry> entryProvider; // ✅ 每次 getObject 新实例"}},{"h":"现场八：BeanPostProcessor 里注入业务 Bean，AOP 静默失效","s":"凯喵写了一个 BPP 去依赖业务 Bean，结果那个业务 Bean 的 @Transactional 全失效了。BPP 极早创建，把业务 Bean 提前初始化，绕过了正常后处理链——代理还没织入。BPP 只依赖基础设施 Bean，要在所…","c":{"lang":"java","code":"// ❌ BPP 依赖业务 Bean -> 提前初始化破坏代理\n// ✅ 用 SmartInitializingSingleton 或 ContextRefreshedEvent\n@Override public void afterSingletonsInstantiated() { /* Bean 全部就绪 */ }"}},{"h":"现场九：用 @Bean 方法互相调用想拿代理，结果拿到原始对象","s":"凯喵在 @Configuration 里 beanA() 内部直接调用 beanB()，以为拿到的是增强后的代理。其实 @Configuration 是 CGLIB 代理类，内部调用会被拦截返回单例；但若写成 @Component 的普…","c":{"lang":"java","code":"@Configuration\npublic class Cfg {\n    @Bean A a() { return new A(b()); }  // ✅ 走容器，拿的是同一个 b 单例\n    @Bean B b() { return new B(); }\n}"}},{"h":"现场十：@DependsOn 顺序错了，依赖的 Bean 还没建好","s":"凯喵用 @DependsOn(\"dbInitializer\") 想保证数据库先初始化，但拼错 Bean 名或漏了，结果初始化顺序仍不对。@DependsOn 只保证初始化顺序，不保证你以为的那个 Bean；名字要和 @Bean/@Com…","c":{"lang":"java","code":"@DependsOn(\"dbInitializer\")   // Bean 名必须精确匹配\n@Component public class CacheWarm { ... }"}},{"h":"现场十一：条件化 Bean 没生效，@Profile / @Conditional 拼错","s":"凯喵写 @Profile(\"prod\") 的 Bean 在 dev 环境也加载了，因为启动参数 --spring.profiles.active 没传或拼错成 pro。条件化 Bean 依赖激活的环境 / 条件类，先用 Environm…","c":{"lang":"bash","code":"# 确认激活的 profile\n--spring.profiles.active=prod"}},{"h":"现场十二：销毁方法没调用，连接池泄漏","s":"凯喵的 @Bean 返回了数据库连接池却没配销毁，close() 从没被调，应用关停时连接泄漏。有 AutoCloseable 的 Bean 容器会自动在关闭时调用 close()；自定义资源显式配 destroyMethod。","c":{"lang":"java","code":"@Bean(destroyMethod = \"close\")   // ✅ 容器关闭时释放资源\npublic DataSource ds() { return new HikariDataSource(); }"}},{"h":"🧑‍💻 程序员视角","s":"prototype 的 Bean 注入到 singleton 里，只会创建一次——因为注入发生在单例初始化时，之后不再重新获取。要每次拿到新实例，得注入 ObjectProvider 或 @Lookup。@Lazy 能「解决」循环依赖…","c":null},{"h":"🎓 博士生视角","s":"Spring 的 Bean 创建流程可以概括为「推断构造器 → 实例化 → 属性填充 → 初始化 → 后置处理」，其中 BeanPostProcessor 是最大的扩展点：AOP 代理、@Autowired 注入、@PostConstr…","c":null},{"h":"📚 考研者视角","s":"面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"Bean 初始化三方式的调用顺序","stem":"关于 @PostConstruct、InitializingBean.afterPropertiesSet()、init-method 的初始化顺序，正确的是？","opts":[{"k":"A","t":"afterPropertiesSet -> @PostConstruct -> init-method"},{"k":"B","t":"@PostConstruct -> afterPropertiesSet -> init-method"},{"k":"C","t":"init-method -> @PostConstruct -> afterPropertiesSet"},{"k":"D","t":"三者顺序由配置决定，没有固定先后"}],"ans":"B","why":"固定顺序：@PostConstruct（BPP 前置阶段）最早，其次 InitializingBean.afterPropertiesSet（invokeInitMethods），最后 init-method（反射调用）。"},{"kind":"output","q":"初始化顺序输出判定","stem":"某 bean 同时标注了三种初始化钩子，依次打印 postConstruct / initializingBean / initMethod。下列输出哪个正确？ text postConstruct;initializingBean;initMethod;","opts":[],"ans":"postConstruct;initializingBean;initMethod;","why":"与生命周期顺序一致：注解最早、接口其次、配置约定最晚。"},{"kind":"choice","q":"singleton 与 prototype 的作用域语义","stem":"关于 Spring 作用域，下列说法准确的是？","opts":[{"k":"A","t":"prototype 每次 getBean 新建且容器负责其销毁"},{"k":"B","t":"singleton 是默认作用域，容器内唯一实例，容器关闭才销毁"},{"k":"C","t":"request 作用域跨请求共享同一实例"},{"k":"D","t":"prototype 注入 singleton 后每次使用都拿到新实例"}],"ans":"B","why":"singleton 为默认、唯一、容器管销毁；prototype 不缓存不销毁；request 同一请求内共享；prototype 注入 singleton 只在创建时注入一次，之后不变。"},{"kind":"fix_error","q":"修复 @Configuration 误写为 @Component 导致多例","stem":"下面配置类漏标 @Configuration，类内 @Bean 互调会每次新建，破坏单例。请修正。 java @Component public class AppConfig { @Bean public Service service(){ return new Service(); } @Bean public Audit audit(){ return new Audit(service(…","opts":[],"ans":"@Configuration public class AppConfig { @Bean public Service service(){ return new Service(); } @Bean public Audit audit(){ return new Audit(service()); } }","why":"标 @Configuration 后 CGLIB 增强子类，覆盖 @Bean 方法使其先查容器单例缓存；类内 audit() 调 service() 也走缓存，保证单例。"},{"kind":"coding","q":"课程表（依赖图环检测，与单例循环依赖同构）","stem":"给定课程先修依赖 prerequisites，判断能否完成所有课程。等价于检测有向图是否存在环——与「Spring 单例循环依赖能否被三级缓存解决」是同一建模：能拓扑排序则无环（可装配），有环则失败（prototype/构造器循环依赖）。","opts":[],"ans":"拓扑排序（Kahn 或 DFS 三色标记）检测有向图环","why":"把依赖建成有向图，能拓扑排序则无环（可完成）；有环则无法完成，类比构造器/prototype 循环依赖必然失败，而单例+Setter 循环依赖因早期引用被解决。"},{"kind":"coding","q":"从零实现迷你生命周期容器（三级缓存）","stem":"参考 Spring 思路，用纯 JDK 实现迷你容器：BeanDefinition 注册、反射实例化、字段填充、Aware 回调、BeanPostProcessor 前后置、初始化与销毁方法，并用三级缓存解决单例循环依赖。","opts":[],"ans":"见参考仓库的最小实现思路（singletonObjects/earlySingletonObjects/singletonFactories 三层 + ObjectFactory）","why":"综合考察生命周期各阶段、反射字段注入、早期引用暴露与三级缓存层级，是本章知识的工程落地。"}],"works":[{"h":"prototype 注入 singleton 不是每次新实例","d":"单例在创建时只注入一次 prototype，之后长期持有同一引用；想每次新实例要用 ObjectProvider.getObject() 或 @Lookup，而不是在字段上直接 @Autowired PrototypeBean。正确写法：@Autowired ObjectProvider<Proto> provider; 用时 pro…"},{"h":"@PostConstruct / @PreDestroy 方法必须无参且返回 void、且类…","d":"方法有参或有返回值、或类只是普通 new 出来的（未进容器），回调都不会触发、也不会报错，排查时极易误以为「逻辑没跑」。正确写法：@PostConstruct void init(){} 且类带 @Component/@@Service 等被扫描。"},{"h":"初始化方法抛异常时，半成品 bean 不会走销毁回调","d":"若在 afterPropertiesSet/@PostConstruct 中抛异常，bean 创建中断，已分配但尚未就绪的对象不会调用 @PreDestroy/DisposableBean，可能泄漏连接/线程池。正确写法：初始化逻辑用 try/finally 兜底资源，或把易失败步骤推迟到 ApplicationRunner（所有单例…"},{"h":"BeanPostProcessor.postProcessAfterInitializati…","d":"自研 BPP 忘记 return bean;，于是该 bean 被替换成 null，所有注入点 getBean 拿到 null → NPE。正确写法：两个钩子都必须 return bean;（或返回包装后的代理），不要返回 null。"},{"h":"构造器循环依赖启动即崩，三级缓存救不了","d":"A、B 互相用构造器注入，实例化阶段对象还没 new 出来，无法暴露早期引用，直接 BeanCurrentlyInCreationException。正确写法：重构拆环，或在注入点加 @Lazy 延迟注入打破环。"},{"h":"@Configuration 漏写变成 @Component，类内 @Bean 互调产出多例","d":"配置类只标 @Component 而非 @Configuration，@Bean 互调是普通方法调用，每次 new，本该单例的依赖出现多实例、状态不一致。正确写法：装配 bean 的配置类一律标 @Configuration，让 CGLIB 增强保证单例共享。"},{"h":"prototype 作用域不会触发销毁回调","d":"容器对 prototype 只负责创建+初始化，不缓存也不注册销毁，@PreDestroy/DisposableBean 永不调用，资源需调用方自行释放，误以为「容器会帮我 close」会泄漏。正确写法：prototype 持有资源的，在调用方用 try-with-resources / 手动 close，别依赖容器销毁。"},{"h":"单例 Bean 里存请求级状态","d":"单例是全局共享的。把当前用户、HttpServletRequest、临时上下文存成成员字段，并发请求会互相覆盖，表现为「A 用户看到 B 用户的数据」这种最危险的一类 bug。 请求级数据走方法参数或 RequestContextHolder；确实需要 per-request 状态就用 @Scope(\"request\")（或 @Req…"}],"asks":[{"q":"说一下 Spring Bean 的完整生命周期（从注册到销毁）。","a":"单例 Bean 在容器启动/首次 getBean 时经历： 1. BeanDefinition 注册：解析成定义存入 beanDefinitionMap； 2. 实例化：反射 ctor.newInstance() 得到半成品； 3. 属性填充：按注入方式把依赖 set 进字段/Setter； 4. Aware 回调：BeanNameAware/BeanFactoryAware/Applicatio…","fu":["为什么 @PostConstruct 比 afterPropertiesSet 早？","BPP 返回 null 会怎样？"],"tag":"通用/字节"},{"q":"Spring 怎么解决循环依赖？为什么用三级缓存而不是两级？","a":"单例 + Setter/字段注入的循环依赖靠三级缓存解决： - 一级 singletonObjects（成品）；二级 earlySingletonObjects（早期引用）；三级 singletonFactories（ObjectFactory）。 流程：实例化 A → 把 A 的早期引用工厂放三级 → 填充需 B → 建 B（同样暴露） → 填 B 需 A → 从三级取 A 早期引用（升二级）注…","fu":["构造器注入的循环依赖为什么救不了？","prototype 循环依赖能解决吗？"],"tag":"通用/腾讯"},{"q":"singleton 里注入 prototype，每次拿到的是新实例吗？怎么解决？","a":"不是。容器只在「单例创建时」注入一次 prototype，之后单例长期持有同一引用，后续 getBean 不会重注。 修复方式： - ObjectProvider：@Autowired ObjectProvider<Proto> p;，用时 p.getObject() 每次取新； - @Lookup 方法（protected abstract Proto proto();，CGLIB 重写返回 g…","fu":["ObjectProvider 和 @Lookup 的实现差异？","prototype 注入 singleton 的单例本身还是单例吗？"],"tag":"通用/京东"},{"q":"@Configuration 和 @Component 里的 @Bean 有什么区别？为什么 @Configuration 要用 CGLIB 代理？","a":"@Configuration 被 CGLIB 增强：Spring 生成其子类并重写每个 @Bean 方法，方法体先查容器单例缓存、命中返回、未命中才 super.xxx() 真正创建。这样类内 @Bean 互调（如 audit() 调 service()）也走容器缓存，保证单例共享。 @Component 不增强：@Bean 互调是普通方法调用，每次 new，单例变多例、状态不一致。 为什么必须代…","fu":["@Configuration 类能用 JDK 动态代理吗？","final 方法会怎样？"],"tag":"通用/阿里"}]},{"id":"spring-ch03","subj":"spring","title":"AOP 与代理机制","summary":"横切关注点与 AOP 术语（切面/切点/通知）；JDK 动态代理与 CGLIB 的字节码原理与适用边界（final 类/方法、接口存在与否）；@Aspect/@Pointcut/@Around；自调用导致代理失效的根因；AOP 在事务、日志…","concepts":[{"id":"spring-ch03/01-jdk-proxy","file":"01-jdk-proxy.md","title":"一、JDK 动态代理：原理与四类通知","kind":"flow","secs":[{"h":"一、JDK 动态代理的工作机制（中立陈述）","s":"JDK 动态代理是 java.lang.reflect.Proxy 在运行时为「一组接口」生成的代理类","c":{"lang":"text","code":"调用方 --接口方法--> 代理对象($Proxy) --invoke--> InvocationHandler --反射 method.invoke(target,args)--> 真实对象"}},{"h":"二、InvocationHandler 与反射委派（中立陈述）","s":"InvocationHandler 是函数式接口（仅 invoke 方法），是 JDK 代理的「拦截中枢」。","c":null}]},{"id":"spring-ch03/02-cglib-boundary","file":"02-cglib-boundary.md","title":"二、CGLIB 子类代理与 JDK/CGLIB 边界","kind":"flow","secs":[{"h":"一、CGLIB 子类代理的原理（中立陈述）","s":"CGLIB（Code Generation Library）通过继承目标类、在运行时生成其子类来代理：","c":{"lang":"text","code":"真实对象 UserService\n   ↑ extends\nUserService$$Enhancer (CGLIB 子类)  — 重写方法：before -> super.method() -> after"}},{"h":"二、JDK 与 CGLIB 的适用边界（中立陈述）","s":"Spring 的取舍（默认策略）：","c":null}]},{"id":"spring-ch03/03-pointcut-order","file":"03-pointcut-order.md","title":"三、切点表达式与通知执行顺序","kind":"flow","secs":[{"h":"一、execution 切点匹配（中立陈述）","s":"切点是「对哪些连接点织入通知」的断言。Spring 用 AspectJ 切点表达式，最常用 execution：","c":null},{"h":"二、通知执行顺序（中立陈述）","s":"Spring AOP 同一切点上有多通知时的顺序：环绕 @Around 包裹其余通知；","c":null}]},{"id":"spring-ch03/04-this-target-selfcall","file":"04-this-target-selfcall.md","title":"四、this 与 target 区别及自调用代理失效","kind":"compare","secs":[{"h":"一、this 与 target 的语义区别（中立陈述）","s":"在 AOP 语境里：","c":null},{"h":"二、同类内部自调用导致代理失效（中立陈述）","s":"当被代理对象的方法 A 内部直接调用同对象的 B（且 B 本应被增强）时，这个内部调用是","c":{"lang":"java","code":"@Service\npublic class OrderService {\n    @Autowired private OrderRepository repo;\n    @Autowired private AuditRepository auditRepo;\n\n    @Autowired @Lazy private OrderService self;   // 自注入拿到的是代理，不是自己\n\n    @Transactional\n    public void save(Order o) {\n…"}}]},{"id":"spring-ch03/05-aop-practical-recipes","file":"05-aop-practical-recipes.md","title":"§5 spring-ch03 实战手记：凯喵带你把 AOP 用「失灵」","kind":"flow","secs":[{"h":"现场一：同类内部方法自调用，通知整段消失","s":"凯喵排查过「加在 createOrder 上的事务为啥没生效」。createOrder 里调了同类的 saveDetail，而 saveDetail 上的 @Transactional 死活不触发。原因：Spring 的 AOP 是代理…","c":{"lang":"java","code":"@Service\npublic class OrderService {\n    @Transactional\n    public void createOrder() {\n        // ❌ this 是原始对象，saveDetail 的代理通知被绕过\n        this.saveDetail();\n    }\n    @Transactional(propagation = REQUIRES_NEW)\n    public void saveDetail() { ... }\n…"}},{"h":"现场二：AopContext.currentProxy() 忘了开 exposeProxy","s":"凯喵写 ((OrderService) AopContext.currentProxy()).saveDetail() 想救自调用，结果拿到 null 抛异常。根因：@EnableAspectJAutoProxy(exposeProxy…","c":{"lang":"java","code":"@Configuration\n@EnableAspectJAutoProxy(exposeProxy = true)   // ✅ 必须显式开\npublic class AopConfig { }\n\n// 使用时通过代理调用，而非 this\n((OrderService) AopContext.currentProxy()).saveDetail();"}},{"h":"现场三：final 类 / final 方法，CGLIB 代理不了","s":"凯喵新来的同事把类写成 final class，结果 Spring 报「无法生成子类」。CGLIB 靠继承 + 方法覆写织入，final 类不能继承、final 方法不能覆写，自然代理不了。规则：要被代理的类和方法别加 final（除非…","c":{"lang":"java","code":"// ❌ final 类，CGLIB 无法生成子类\nfinal class PaymentService { ... }\n\n// ✅ 去掉 final，让 CGLIB 能继承\n@Component\nclass PaymentService {\n    public void pay() { ... }   // 可被代理\n}"}},{"h":"现场四：private 方法上的 @Transactional 不生效","s":"凯喵见过有人在 private void inner() 上写 @Transactional，期待它独立开事务。但 Spring 代理只能拦截外部可调用的方法（public），private 方法根本进不了代理的拦截逻辑，注解等于白写…","c":{"lang":"java","code":"// ❌ private + @Transactional，代理拦截不到\n@Transactional\nprivate void inner() { ... }\n\n// ✅ public 才能被代理拦截\n@Transactional\npublic void outer() { ... }"}},{"h":"现场五：@Around 不调 proceed，业务直接被吞","s":"凯喵 review 代码看到有人写 @Around 但忘了 joinPoint.proceed()，结果方法体根本不执行——所有请求返回 null。Around 的本质是「包裹」，你必须手动调 proceed 才把控制权交还给原方法，否…","c":{"lang":"java","code":"@Around(\"pointcut()\")\npublic Object around(ProceedingJoinPoint pjp) throws Throwable {\n    long t0 = System.nanoTime();\n    try {\n        return pjp.proceed();   // ✅ 必须调 proceed，否则原方法不执行\n    } finally {\n        log.info(\"{} 耗时 {}ms\", pjp.getSignature(), (System.nanoTime()-t0)/1_000_000);\n    }\n}"}},{"h":"现场六：切点表达式太宽，把内部方法也织进去了","s":"凯喵见过 @Around(\"execution( com.x...(..))\") 把 toString、hashCode 全包了，日志刷屏还死循环（切面里调 toString 又触发切面）。切入点要精确：限定 service 包、限定特…","c":{"lang":"java","code":"// ❌ 太宽，连 toString/getter 都织入\n@Pointcut(\"execution(* com.x..*.*(..))\") \n\n// ✅ 只切 service 包下 public 方法\n@Pointcut(\"execution(public * com.x.service..*.*(..))\")\n\n// ✅ 或用注解驱动，最干净\n@Pointcut(\"@annotation(com.x.LogTime)\")"}},{"h":"现场七：多个切面顺序混乱，日志和事务谁先谁后说不清","s":"凯喵的团队曾因多个 @Aspect 顺序不定，出现「事务回了滚但日志记了成功」。用 @Order 或实现 Ordered 明确优先级：数字越小越先执行（Outer 先入）。全局切面（如日志/鉴权）用低值先执行，事务用较高值后执行。","c":{"lang":"java","code":"@Aspect\n@Order(1)   // 先执行（最外层）\npublic class LogAspect { ... }\n\n@Aspect\n@Order(10)  // 后执行（更靠近目标方法）\npublic class TxAspect { ... }"}},{"h":"现场八：@After 读返回值永远是 null","s":"凯喵新人想在「后置」里拿返回值做统计，写在 @After 里拿到 null。混淆了 @After（等同 finally，异常/正常都跑，拿不到返回值）和 @AfterReturning（只在正常返回后跑，能拿到 returning 参数…","c":{"lang":"java","code":"@After(\"pointcut()\")\npublic void after() { /* 拿不到返回值，等同于 finally */ }\n\n@AfterReturning(pointcut = \"pointcut()\", returning = \"ret\")\npublic void afterReturning(Object ret) {\n    log.info(\"返回值 = {}\", ret);   // ✅ 这里能拿到\n}"}},{"h":"现场九：this 与 target 指向不同，切点匹配错对象","s":"凯喵排查权限拦截失效，发现表达式用了 this(AdminService)。this 匹配的是代理对象类型，target 匹配的是被代理的真实对象类型。当接口代理时二者可能不同，权限这类应切真实类型的场景要用 target，别用 thi…","c":{"lang":"java","code":"// this：代理对象（可能是接口代理）\n@Pointcut(\"this(com.x.AdminService)\")\n// target：真实被代理对象\n@Pointcut(\"target(com.x.AdminService)\")"}},{"h":"现场十：JDK 动态代理要求目标有接口","s":"凯喵把没实现接口的类交给 Spring 默认配置，结果注入时报「找不到代理」。默认「有接口用 JDK 动态代理、无接口用 CGLIB」。若强制 proxyTargetClass=false 又没接口，就直接失败。Boot 2.x 起默认…","c":{"lang":"java","code":"@Configuration\n@EnableAspectJAutoProxy(proxyTargetClass = true)  // ✅ 强制 CGLIB，可代理具体类\npublic class AopConfig { }"}},{"h":"现场十一：切面里捕获了异常，事务无法回滚","s":"凯喵的同事在业务方法里 try { ... } catch (Exception e) { log.error(e); } 吞了异常，结果事务不回滚——因为 @Transactional 只认抛出到代理层的异常。要回滚就重抛，或用 Tr…","c":{"lang":"java","code":"@Transactional\npublic void biz() {\n    try {\n        dao.insert();\n    } catch (Exception e) {\n        // ❌ 吞掉异常 -> 事务提交\n        TransactionAspectSupport.currentTransactionStatus()\n            .setRollbackOnly();   // ✅ 显式标记回滚\n        throw e;                  // ✅ 或重抛给代理\n…"}},{"h":"现场十二：用 Aspect 做鉴权，却漏了内部入口","s":"凯喵的权限切面只切 Controller，结果有人直接调 Service 绕过鉴权。AOP 只拦截它切面覆盖的入口，不是全局防火墙。安全类增强要切到「所有外部可达入口」（Controller + 内部 RPC），并配合网关层鉴权做纵深防…","c":{"lang":"java","code":"// ❌ 只切 Controller，Service 直调绕过\n@Pointcut(\"within(com.x.controller..*)\")\n// ✅ 切到业务入口更稳（再配合网关）\n@Pointcut(\"within(com.x.service..*) || within(com.x.controller..*)\")"}},{"h":"🧑‍💻 程序员视角","s":"同类内部方法自调用（this.method()）不走代理，@Transactional/@Cacheable 整段失效——因为调用没经过代理对象。要生效得注入自身代理（AopContext.currentProxy() 需开 expos…","c":null},{"h":"🎓 博士生视角","s":"Spring AOP 是「运行期代理」而非「编译期织入」：JDK 动态代理基于接口，CGLIB 基于继承生成子类。这决定了它的能力边界——只能拦截「经代理对象的公开方法调用」，无法拦截自调用、构造器、静态方法与 final 方法。Asp…","c":null},{"h":"📚 考研者视角","s":"面试必问：","c":null}]}],"exams":[{"kind":"choice","q":"JDK 动态代理的实现前提","stem":"关于 JDK 动态代理 Proxy.newProxyInstance，下列说法正确的是？","opts":[{"k":"A","t":"可以代理任意普通类（无需接口）"},{"k":"B","t":"必须传入接口数组，生成的代理类实现这些接口"},{"k":"C","t":"生成的代理类 extends 业务类以重写方法"},{"k":"D","t":"InvocationHandler.invoke 的第一个参数是被代理的真实对象"}],"ans":"B","why":"JDK 动态代理要求传入接口数组，生成的 $Proxy 实现这些接口；因已 extends Proxy 受单继承限制，无法再继承业务类；invoke 第一个参数是代理对象而非 target。"},{"kind":"output","q":"通知嵌套执行顺序输出","stem":"某切点同时配置 @Around、@Before、目标方法、@After、@AfterReturning。下列输出哪个符合 Spring 执行顺序？ text [Around] start [Before] before method [Target] businessMethod() [After] after method (always) [AfterReturning] method ret…","opts":[],"ans":"[Around] start [Before] before method [Target] businessMethod() [After] after method (always) [AfterReturning] method returned normally [Around] end","why":"顺序为 Around 进入 → Before → 目标 → After(始终) → AfterReturning(正常) → Around 退出；@After 像 finally 无论成败都执行。"},{"kind":"choice","q":"CGLIB 代理的限制","stem":"关于 CGLIB 子类代理，下列说法准确的是？","opts":[{"k":"A","t":"CGLIB 通过实现接口生成代理，与 JDK 动态代理原理相同"},{"k":"B","t":"CGLIB 无法代理 final 类与 final/private 方法（无法继承/重写）"},{"k":"C","t":"CGLIB 代理的目标类必须实现至少一个接口"},{"k":"D","t":"CGLIB 生成的代理类调用目标方法时走反射 method.invoke"}],"ans":"B","why":"CGLIB 通过继承目标类、重写方法实现；final 类不可继承、final/private 方法不可重写，故无法代理；它不要求接口，且方法为直接调用（非反射）。"},{"kind":"fix_error","q":"修复同类自调用导致事务失效","stem":"下面 OrderService 的 create() 内部 this.pay() 调用使 pay() 上的 @Transactional 不生效（自调用绕过代理）。请修正。 java @Service public class OrderService { @Transactional public void create() { this.pay(); } @Transactional publ…","opts":[],"ans":"@Service public class OrderService { @Autowired OrderService self; // 自注入拿到代理 @Transactional public void create() { self.pay(); } @Transactional public void pay…","why":"自调用走 this（真实对象）绕过代理，事务不生效；用自注入/拆分 Bean 让调用经过代理即可恢复增强。"},{"kind":"coding","q":"从零实现迷你 AOP 容器（JDK 代理 + 责任链）","stem":"参考 Spring 思路，用纯 JDK 实现迷你 AOP：定义 Advice 接口（before/after），用 JDK 动态代理 + InvocationHandler 把多个 Advice 串成责任链，支持按方法名（简化切点）过滤是否织入。等价于把「拦截器链」工程化落地。","opts":[],"ans":"见参考仓库的最小实现（Proxy + InvocationHandler + List<Advice> 责任链 + 切点过滤）","why":"综合考察 JDK 代理、反射委派、责任链顺序与切点匹配，是本章知识的工程落地。"},{"kind":"coding","q":"最小栈（装饰器式增强：在基础结构上叠加行为，与代理/Advice 思想同构）","stem":"设计一个支持 push/pop/top 且在常数时间取最小值的栈。其「在基础栈上叠加 min 追踪」的结构，与 AOP 在目标对象上叠加通知（Advice）是同一「装饰/代理增强」思想。","opts":[],"ans":"维护辅助最小栈（或每元素携带当前最小值），push/pop 同步维护","why":"装饰器/代理增强思想：基础结构只管存取，附加行为（min 追踪 / 日志 / 事务）在外层透明叠加；与本章 Advice 包裹目标方法的模式同构。"}],"works":[{"h":"同类方法内部自调用绕过代理（最经典）","d":"被代理对象的 save() 内部 this.update()， this 是真实对象而非代理，update() 上的 @Transactional/@Async 等通知全部失效。 正确写法：把 update() 拆到另一个 Bean 注入调用，或用 AopContext.currentProxy() / 自注入拿到代理再调。"},{"h":"把 InvocationHandler.invoke 的第一个参数当 target","d":"第一个参数是代理对象， 不是被代理的真实对象；用它去 == 比较或递归调自身会死循环/永不相等（见 ex08）。 真实对象应作为字段单独持有，用 method.invoke(target, args) 委派。"},{"h":"反射异常被 InvocationTargetException 包多层","d":"method.invoke 抛出的业务异常会被包成 InvocationTargetException，直接 catch(Exception e) 拿到的是包装异常、类型判断全错。 正确写法：捕获后取 e.getCause() 得到真实异常（见 ex03）。"},{"h":"JDK 动态代理只能代理接口，传普通类直接抛异常","d":"Proxy.newProxyInstance 要求传入的是 接口数组；若误传具体类会抛 IllegalArgumentException: ... is not an interface（见 ex06）。 代理具体类必须改用 CGLIB。"},{"h":"CGLIB 无法代理 final 类 / final、private 方法","d":"因 CGLIB 靠「继承 + 重写」， final 不可继承/不可重写，启动即报 Cannot subclass final class（见 ex12）。 正确写法：去掉 final，或改用基于接口的 JDK 代理。"},{"h":"切点写得过宽导致全量拦截","d":"execution( (..)) 会把 Spring 内部 Bean、toString/hashCode 也织入，引发栈溢出或性能雪崩。正确写法：收窄到具体包/类/方法，或改用 @annotation 注解切点。"},{"h":"混淆 @After 与 @AfterReturning","d":"@After 类似 finally，无论正常还是异常都执行， 且拿不到返回值；@AfterReturning 只在正常返回后执行、能拿到返回值；异常时走的是 @AfterThrowing。 在 @After 里读返回值是 null，应在 @AfterReturning 里读。"},{"h":"AopContext.currentProxy() 忘记开 exposeProxy","d":"想用 currentProxy() 解决自调用， 却没在 @EnableAspectJAutoProxy(exposeProxy = true)，运行拿到 null 抛异常。 正确写法：显式开启，或更推荐「拆 Bean」的方案。"}],"asks":[{"q":"JDK 动态代理和 CGLIB 的区别是什么？Spring 默认用哪种？","a":"JDK 动态代理：基于接口，运行时生成接口实现类（$Proxy），所有方法路由到 InvocationHandler.invoke，内部反射调用目标；只能代理接口。 CGLIB：基于继承，运行时用 ASM 生成目标类的子类并重写可覆写方法，在 super.xxx() 前后织入 MethodInterceptor；无需接口，但不能代理 final 类 / final / private 方法。 Sp…","fu":["CGLIB 为什么不能代理 final 方法？","JDK 代理的方法调用为什么要反射，性能影响多大？"],"tag":"通用/字节"},{"q":"为什么 @Transactional 在同类方法互相调用时会失效？怎么解决？","a":"Spring 的事务是基于代理的 AOP 增强：只有「从代理对象进入」的调用才会被拦截并开启事务。当 serviceA() 内部用 this.serviceB() 调用同类方法时，this 是真实对象而非代理，调用直接命中真实方法、不经过拦截层，于是 serviceB() 上的事务通知不触发。 解决方案（按推荐度）： 1. 把被调方法抽到另一个 Spring Bean，用依赖注入调用（最干净、可测…","fu":["AopContext.currentProxy() 的原理是什么？","AspectJ 编译期织入能解决自调用吗？为什么？"],"tag":"通用/腾讯"},{"q":"多个 AOP 通知（@Around/@Before/@After 等）在一个切点上，执行顺序是怎么样的？","a":"同一切点多通知的执行顺序（单通知情况下）： @Around 进入 → @Before → 目标方法 → @After（无论成败都执行，类似 finally）→ @AfterReturning（正常返回）/ @AfterThrowing（异常）→ @Around 退出返回。 即 @Around 包裹其余通知，@After 类通知在归程像 finally 一样始终执行，异常时走 @AfterThrow…","fu":["@After 和 @AfterReturning 能同时触发吗？","@Order 的数值大小与执行先后如何对应？"],"tag":"通用/京东"},{"q":"AOP 里的 this 和 target 分别指什么？在切点表达式里有区别吗？","a":"target：被代理的真实对象（业务实现，即 Handler 持有的 target / CGLIB 的 super）。 - this：代理对象本身（$Proxy 或 $$Enhancer 实例）。 二者是不同对象：proxy == target 恒为 false（见 ex08）。 切点表达式区别：target(X) 匹配真实对象类型，this(X) 匹配代理对象类型。在 JDK 代理下 this…","fu":["CGLIB 代理下 this instanceof 业务类 是否为 true？","为什么要用 AopContext.currentProxy() 拿 this？"],"tag":"通用/阿里"}]},{"id":"spring-ch04","subj":"spring","title":"SpringBoot 自动配置与起步依赖","summary":"@SpringBootApplication 三合一注解；SPI 机制的演进（spring.factories → AutoConfiguration.imports）；@ConditionalOnClass/@ConditionalOnM…","concepts":[{"id":"spring-ch04/01-application-and-startup","file":"01-application-and-startup.md","title":"一、@SpringBootApplication 的「三合一」与启动主干","kind":"flow","secs":[{"h":"1. 一个注解，三个职责","s":"@SpringBootApplication 本身几乎不做事，它是一组注解的复合（composed annotation）：","c":{"lang":"java","code":"@SpringBootApplication\npublic class DemoApplication {\n    public static void main(String[] args) { SpringApplication.run(DemoApplication.class, args); }\n}"}},{"h":"2. SpringApplication.run 的启动主干","s":"这解释了一个常见现象：即使某个自动配置类的条件不满足，它的类名依然会出现在","c":{"lang":"text","code":"SpringApplication.run()\n └─ new SpringApplication(...)                  /* 推断应用类型 SERVLET/REACTIVE/NONE */\n └─ run(args)\n     ├─ 1. 准备 Environment（加载配置源、命令行参数、profile）\n     ├─ 2. 打印 Banner\n     ├─ 3. 创建 ApplicationContext（按类型选 Servlet/Reactive/Annotation）\n     ├─ 4. prepareContext：把主配置类注册为 BeanDefinition\n     ├─ 5. refreshContext()   ← 就是 spring-ch01 讲过的 AbstractApplicationContext#refresh\n     │      ├─ invokeBeanFactoryPostProcessors()\n…"}}]},{"id":"spring-ch04/02-auto-config-spi-and-conditions","file":"02-auto-config-spi-and-conditions.md","title":"二、自动配置的 SPI 加载与条件装配","kind":"flow","secs":[{"h":"1. 候选清单从哪来：SPI 机制的演进","s":"问题在于：这个文件是万能注册表，自动配置、初始化器、监听器、失败分析器等全挤在一起，","c":{"lang":"properties","code":"org.springframework.boot.autoconfigure.EnableAutoConfiguration=\\\ncom.example.FooAutoConfiguration,\\\ncom.example.BarAutoConfiguration"}},{"h":"2. 条件装配：决定「装不装」的那组注解","s":"所有条件的总入口是 Condition 接口：","c":{"lang":"java","code":"@FunctionalInterface\npublic interface Condition {\n    boolean matches(ConditionContext context, AnnotatedTypeMetadata metadata);\n}"}},{"h":"3. 关键约束：顺序决定结果","s":"自动配置类必须晚于用户的 @Configuration 被处理，否则会「重复注册」。","c":null}]},{"id":"spring-ch04/03-config-binding-and-starter","file":"03-config-binding-and-starter.md","title":"三、配置绑定、优先级与自定义 starter","kind":"compare","secs":[{"h":"1. @ConfigurationProperties vs @Value","s":"只有零散的、需要 SpEL 的单个值才用 @Value。","c":{"lang":"text","code":"my-name      → my-name\nmyName       → my-name\nmy_name      → my-name\nMY_NAME      → my-name\napp.myName   → app.my-name"}},{"h":"2. 配置优先级与 profile","s":"同一层级内，profile 专属文件覆盖通用文件：","c":{"lang":"text","code":"application.properties          ← 通用\napplication-prod.properties     ← 激活 prod 时覆盖上面的同名键"}},{"h":"3. 自定义 starter 的两模块结构","s":"若合成一个模块，使用方引入后，其中的自动配置类会落在被组件扫描的包路径下","c":{"lang":"text","code":"xxx-spring-boot-autoconfigure/        ← 自动配置实现\n├── pom.xml                           （依赖 spring-boot-autoconfigure，scope=optional）\n└── src/main/java/.../XxxAutoConfiguration.java\n    src/main/resources/META-INF/spring/\n        org.springframework.boot.autoconfigure.AutoConfiguration.imports\nxxx-spring-boot-starter/              ← 聚合依赖\n└── pom.xml                           （只依赖 autoconfigure + 具体实现库）"}}]},{"id":"spring-ch04/04-autoconfig-practical-recipes","file":"04-autoconfig-practical-recipes.md","title":"SpringBoot 自动配置实战手记：凯喵的十二次「Bean 没装上，启动就崩」","kind":"flow","secs":[{"h":"开场：一个空项目为什么能跑起来","s":"spring-boot-starter-web 加一个 main 方法就能起一个带 Tomcat 的 Web 应用。这背后是三件事的叠加：","c":{"lang":"java","code":"@SpringBootApplication\npublic class App {\n    public static void main(String[] args) {\n        SpringApplication.run(App.class, args);\n    }\n}"}},{"h":"收尾：自动配置是「有条件生效的默认值」","s":"凯喵最后总结：SpringBoot 自动配置的本质是给出一套合理的默认值，并允许你在任何一点覆盖它。三个机制共同实现这件事：","c":null}]}],"exams":[{"kind":"choice","q":"@SpringBootApplication 的组成","stem":"@SpringBootApplication 等价于以下哪组注解的组合？","opts":[{"k":"A","t":"@SpringBootConfiguration + @EnableAutoConfiguration + @Compo…"},{"k":"B","t":"@Configuration + @EnableWebMvc + @ComponentScan"},{"k":"C","t":"@SpringBootConfiguration + @EnableAutoConfiguration + @Mappe…"},{"k":"D","t":"@Configuration + @EnableTransactionManagement + @ComponentSc…"}],"ans":"A","why":"三者分工：@SpringBootConfiguration 标记主配置类（本质是特殊 @Configuration）、@EnableAutoConfiguration 通过 SPI 引入自动配置类、@ComponentScan 扫描当前包及子包。注意 @ComponentScan 只扫自己的包，官方自动配置类不在其中，靠 SPI 加载。"},{"kind":"choice","q":"@ConditionalOnMissingBean 失效的根因","stem":"在用户自己的 @Configuration 类中标注 @ConditionalOnMissingBean 时，经常出现「判定结果不符合预期」的情况。最本质的原因是？","opts":[{"k":"A","t":"该注解只对 @Bean 方法有效，对类无效"},{"k":"B","t":"判定依赖注册顺序，而用户的配置类与自动配置类的处理次序不确定"},{"k":"C","t":"该注解只能用于 @Component，不能用于 @Configuration"},{"k":"D","t":"它需要配合 @DependsOn 才能生效"}],"ans":"B","why":"@ConditionalOnMissingBean 在 BeanDefinition 阶段求值，结论取决于「此刻容器里已有什么」。自动配置类被约定为最后处理，因此在该处使用是安全的；在用户配置类中使用则受顺序影响，结论不可靠。需要控制顺序时用 @AutoConfigureBefore/After。"},{"kind":"output","q":"条件结果推导","stem":"给定：类路径上存在 HikariDataSource，不存在 RedisOperations；容器中还没有 dataSource Bean。以下两个自动配置类，哪些会生效？ java @ConditionalOnClass(name = \"com.zaxxer.hikari.HikariDataSource\") @ConditionalOnMissingBean(name = \"dataSourc…","opts":[],"ans":"PoolAutoConfiguration 生效，RedisAutoConfiguration 不生效","why":"PoolAutoConfiguration 两个条件同时满足（类存在 + 容器无同名 Bean），故生效；RedisAutoConfiguration 的 @ConditionalOnClass 不满足（类路径无 RedisOperations），故不生效。注意 @ConditionalOnClass 要用 name 字符串形式，直接写 .class 会在类缺失时抛 NoCla…"},{"kind":"fix_error","q":"修复条件注解的写法","stem":"下面的自动配置类在依赖缺失时会直接启动失败，请指出并修复： java @Configuration @ConditionalOnClass(RedisOperations.class) public class MyRedisAutoConfiguration { @Bean @ConditionalOnMissingBean public MyRedisTemplate myRedisTempl…","opts":[],"ans":"@Configuration @ConditionalOnClass(name = \"org.springframework.data.redis.core.RedisOperations\") public class MyRedisAutoConfiguration { @Bean @ConditionalOnMis…","why":"@ConditionalOnClass(RedisOperations.class) 会在类加载阶段就尝试解析 RedisOperations，当依赖不存在时抛出 NoClassDefFoundError，条件根本没机会求值。正确写法是用 name 属性传全限定名字符串，让判定只依赖类名比较。"},{"kind":"coding","q":"自动配置的拓扑排序","stem":"给定自动配置类之间的依赖关系 Map<String, List<String>> deps（含义：key 依赖列表中的所有类，即它们必须先于 key 生效），输出一个合法的生效顺序；若存在环，则输出环中涉及的类。 输入（示例）： MyBatisAutoConfiguration -> [DataSourceAutoConfiguration] TransactionAutoConfiguratio…","opts":[],"ans":"DataSourceAutoConfiguration MyBatisAutoConfiguration TransactionAutoConfiguration","why":"Spring 处理 @AutoConfigureAfter/Before 的方式与此同构：把相对顺序约束建成有向图，做拓扑排序（Kahn 算法，O(V+E)）。出现环时无法线性化，Spring 退化为字典序并打印告警，以保证应用始终能启动（可用性优先）。order.size() != deps.size() 即为有环判据。"},{"kind":"coding","q":"课程表 II（拓扑排序模板题）","stem":"本题是自动配置顺序问题的通用模板：给定先修课程关系，返回一个合法的学习顺序；若存在环则返回空数组。请到 LeetCode 完成该题，体会与 @AutoConfigureAfter 排序同构的算法。","opts":[],"ans":"","why":"与自动配置拓扑排序完全同构：入度表 + 队列（或优先队列）。差异仅在「同层顺序」是否要求确定：LeetCode 判定任意合法顺序，而 Spring 需要确定性，故用类名字典序兜底。"}],"works":[{"h":"@SpringBootApplication 的扫描范围只覆盖主类所在包及其子包","d":"主类放在 com.example.demo，而业务代码在 com.example.service，@ComponentScan 扫不到， 表现为「Bean 找不到」。正确做法：把主类放在所有业务包的最外层 （如 com.example），或显式 @ComponentScan(basePackages = \"com.example\")…"},{"h":"@ConditionalOnMissingBean 的判定依赖「注册顺序」，因此自动配置类必…","d":"若自动配置类先被执行，它看不到用户定义的 Bean，就会把自己的默认 Bean 也注册进去， 导致「我明明写了 Bean 却生效了两个」。正确认知：@ConditionalOnMissingBean 只在 自动配置类里才安全；配套的是 @AutoConfigureBefore/After 与自动配置的 「最后加载」约定。在用户自己的…"},{"h":"spring.factories 与 AutoConfiguration.imports 混…","d":"Spring Boot 2.7 起，自动配置类改用 META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports （每行一个全限定类名，无 key）；而 spring.factories 里若仍保留 EnableAutoConfigur…"},{"h":"@ConfigurationProperties 绑定失败不报错，只是静默为 null","d":"与 @Value 不同，@ConfigurationProperties 的松散绑定对「拼错的 key」是静默忽略的， 排查时极易误判为「配置没读到」。正确做法：加 @Validated + @NotNull/@NotBlank 校验，或用 spring-boot-configuration-processor 生成元数据让 IDE…"},{"h":"配置文件优先级记混","d":"实际生效顺序（从高到低）大致为： 命令行参数 → SPRING_APPLICATION_JSON → ServletConfig/Context 参数 → JNDI → Java System properties → 操作系统环境变量 → application-{profile}.properties （jar 包外） → app…"},{"h":"把 starter 写成一个大模块，且不加 optional/provided","d":"自定义 starter 应拆成 autoconfigure 模块（含自动配置源码，依赖 spring-boot-autoconfigure 且标 optional）与 starter 模块（只做 autoconfigure + 具体实现的聚合依赖）。 写成单模块会把自动配置类暴露给使用者并被组件扫描到，破坏「自动配置由 SPI 驱动」…"},{"h":"@ConditionalOnProperty 的 havingValue 是精确字符串比较","d":"不带 havingValue 时只要属性存在且不等于 false 就生效；一旦写了 havingValue=\"true\"，值必须恰好是 \"true\"——配成 1、TRUE、yes 都不匹配，条件静默不成立，Bean 就是不注册，日志里也未必有痕迹。 布尔开关统一写 havingValue=\"true\" + matchIfMissing…"},{"h":"BOM 与 parent 混用，版本被自己写死的号覆盖","d":"spring-boot-starter-parent 与 spring-boot-dependencies 同时引入时，<dependencyManagement> 的 import 顺序决定最终版本（后者覆盖前者）；而在 <dependencies> 里手写版本号会直接让 BOM 失效，于是同一项目里 Spring 各组件的版本悄悄…"}],"asks":[{"q":"SpringBoot 自动配置的原理是什么？","a":"四步：① @SpringBootApplication 内含 @EnableAutoConfiguration；② 它 @Import 了 AutoConfigurationImportSelector；③ 该 Selector 通过 SPI 读取候选清单（2.7 前是 META-INF/spring.factories 的 EnableAutoConfiguration 键，2.7+/3.x 是…","fu":["为什么 3.x 要弃用 spring.factories 承载自动配置？","自动配置类为什么要用 @AutoConfigureAfter 声明顺序？"],"tag":"通用/阿里"},{"q":"@ConditionalOnMissingBean 为什么只在自动配置类里可靠？","a":"它判定的是「此刻容器里是否已有该 Bean 的定义」，而这一结论完全取决于评估顺序。 Spring Boot 的约定是：用户配置类先处理，自动配置类最后处理（由 AutoConfigurationGroup + @AutoConfigureOrder 保证）。因此只有在自动配置类里，「用户已定义的 Bean」才一定已经在容器中，@ConditionalOnMissingBean 才能正确回落。 在…","fu":["条件求值发生在 Bean 生命周期哪个阶段？","它能否感知到通过 @Bean 方法注册但尚未实例化的 Bean？"],"tag":"通用/美团"},{"q":"如何自定义一个 starter？为什么官方推荐拆成两个模块？","a":"步骤： 1. 建 xxx-spring-boot-autoconfigure：写 XxxAutoConfiguration，标注 @Configuration + 条件注解（@ConditionalOnClass、@ConditionalOnMissingBean）； 2. 在 src/main/resources/META-INF/spring/org.springframework.boot.…","fu":["spring-boot-autoconfigure 为什么标 optional？","starter 里如果不加 @ConditionalOnMissingBean 会有什么后果？"],"tag":"通用/腾讯"},{"q":"SpringBoot 配置的优先级顺序是怎样的？","a":"从高到低（同一层级内 profile 专属覆盖通用）： 1. 命令行参数 --key=value 2. SPRING_APPLICATION_JSON 3. ServletConfig / ServletContext 参数 4. JNDI 5. Java System properties（-Dkey=value） 6. 操作系统环境变量 7. jar 包外 application-{profi…","fu":["为什么要设计成位置优先于 profile？","spring.config.location 与 spring.config.additional-location 的…"],"tag":"通用/运维"}]},{"id":"spring-ch05","subj":"spring","title":"Web 层：REST 控制器与参数校验","summary":"@RestController/@RequestMapping 与路径匹配；参数绑定（@RequestBody/@PathVariable/@RequestParam）与内容协商；统一响应体与 @ControllerAdvice 全局异常处…","concepts":[{"id":"spring-ch05/01-rest-controller-and-mapping","file":"01-rest-controller-and-mapping.md","title":"一、REST 控制器与请求映射","kind":"timeline","secs":[{"h":"1. @RestController 的语义与请求映射","s":"@RestController 是 @Controller 与 @ResponseBody 的组合注解；@RequestMapping 在类级定义基准路径前缀，在方法级定义子路径与 HTTP method（@GetMapping 等是它…","c":null},{"h":"2. 状态码选择与第一性的幂等性","s":"REST 用 HTTP 状态码表达结果；幂等性指「多次相同请求产生相同副作用」。GET/PUT/DELETE 幂等，POST 不幂等。创建资源用 POST（201 + Location），更新整资源用 PUT（幂等，200/204），部…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"java","code":"import java.util.*;\npublic class Main {\n    interface Handler { String handle(String body); }\n    public static void main(String[] a){\n        Map<String,Handler> routes = new LinkedHashMap<>();\n        routes.put(\"GET /users\", (b)->\"200 OK [list 2 users]\");\n        routes.put(\"POST /users\", (b)->\"201 Created [id=3]\");\n        String[] reqs = {\"GET /users\",\"POST /users\",\"DELETE /users\"};\n        for(String r: reqs){\n…"}}]},{"id":"spring-ch05/02-parameter-binding","file":"02-parameter-binding.md","title":"二、参数绑定与内容协商","kind":"flow","secs":[{"h":"1. 三类参数绑定：@RequestParam / @PathVariable / @Req…","s":"三者分别吃不同的请求位置：@RequestParam 取查询串或表单字段（?page=2），@PathVariable 取路径模板变量（/users/{id}），@RequestBody 把整个请求体（通常 JSON）反序列化成对象。绑…","c":null},{"h":"2. 内容协商与消息转换器链","s":"内容协商（Content Negotiation）指服务器根据客户端 Accept 头选择返回格式（JSON/XML）。Spring 用 HttpMessageConverter 链：写响应时按 Accept 与转换器支持类型匹配；读请…","c":null},{"h":"可运行代码：四种参数来源的绑定写法","s":"同一个 Controller 里四种来源并列摆出来，@PathVariable / @RequestParam / @RequestBody /","c":{"lang":"java","code":"@RestController\n@RequestMapping(\"/api/orders\")\npublic class OrderController {\n\n    // 路径变量：GET /api/orders/42?detail=true\n    @GetMapping(\"/{id}\")\n    public Order get(@PathVariable Long id,\n                     @RequestParam(defaultValue = \"false\") boolean detail) {\n        return service.find(id, detail);\n…"}}]},{"id":"spring-ch05/03-validation","file":"03-validation.md","title":"三、参数校验：Bean Validation 的元数据模型","kind":"flow","secs":[{"h":"1. JSR-303/380 的元数据模型：约束注解 + ConstraintValidat…","s":"Bean Validation 把校验规则表达为注解（元数据）贴在字段上（@NotNull/@Size/@Min），运行时由校验引擎通过反射读取这些注解并调用对应的 ConstraintValidator 执行。规则与代码解耦。","c":null},{"h":"2. 分组校验与级联校验","s":"分组校验（groups）让同一对象在不同场景用不同规则：例如新增时 id 为空、更新时 id 必填。级联校验（@Valid 嵌套）让对象里的子对象也被一并校验。","c":null}]},{"id":"spring-ch05/04-exception-handling-and-dto","file":"04-exception-handling-and-dto.md","title":"四、全局异常处理与 DTO 隔离","kind":"flow","secs":[{"h":"1. @ControllerAdvice 全局异常处理与异常→状态码映射","s":"@ControllerAdvice 是集中式的横切Advice，配合 @ExceptionHandler 捕获所有 Controller 抛出的特定异常，统一转成「状态码 + 错误体」，避免每个方法写 try-catch。","c":null},{"h":"2. DTO 与实体分离：防止敏感字段泄露","s":"DTO（Data Transfer Object）是对外传输的数据结构，Entity 是持久层对象。对外永远返回 DTO，不返回 Entity——尤其要裁剪掉 password、salt 等敏感字段，否则会直接序列化泄露。","c":null}]},{"id":"spring-ch05/05-rest-practical-recipes","file":"05-rest-practical-recipes.md","title":"凯喵实战手记 · REST 接口：那些「本地通、线上炸」的现场","kind":"flow","secs":[{"h":"现场 1：@RequestBody 与 @RequestParam 用错，参数永远是空","s":"请求体是 JSON 时用 @RequestBody，查询串或表单参数用 @RequestParam。凯喵：最常见的错误是 POST 传 JSON 却用 @RequestParam 接，结果参数全是 null，还挺纳闷「前端明明传了」。先…","c":{"lang":"java","code":"@PostMapping(\"/users\")\npublic User create(@RequestBody UserDTO dto) { ... }"}},{"h":"现场 2：路径变量与查询参数别混","s":"/users/{id} 里的 {id} 用 @PathVariable 接，?page=1 用 @RequestParam 接。凯喵：名字对不上时，@PathVariable(\"id\") 要显式指定；不指定且编译没开 -paramete…","c":{"lang":"java","code":"@GetMapping(\"/users/{id}\")\npublic User get(@PathVariable(\"id\") Long id) { ... }"}},{"h":"现场 3：日期与枚举的绑定格式","s":"@RequestParam 接日期默认按 ISO 格式，前端传 2026/11/02 就 400。凯喵：用 @DateTimeFormat(pattern = \"yyyy-MM-dd\") 显式声明格式，枚举则确认大小写与 Convert…","c":{"lang":"java","code":"@GetMapping(\"/orders\")\npublic List<Order> list(@RequestParam @DateTimeFormat(pattern=\"yyyy-MM-dd\") LocalDate day) { ... }"}},{"h":"现场 4：校验注解要配 @Valid 才生效","s":"@NotNull、@Size 这些注解本身不会自动触发，必须参数上加 @Valid（或 @Validated）才会执行校验。凯喵：很多人加了约束注解却没加 @Valid，以为已经校验了，结果脏数据一路进库。校验不生效是「静默失败」，比报…","c":{"lang":"java","code":"@PostMapping(\"/users\")\npublic User create(@Valid @RequestBody UserDTO dto) { ... }"}},{"h":"现场 5：嵌套对象的校验要加 @Valid","s":"DTO 里嵌套了另一个对象，只在外层加 @Valid 不够，内层字段的约束不会被执行。凯喵：嵌套字段上也要加 @Valid，才能级联校验。这个坑在「地址、联系人」这类嵌套结构里特别常见，表面校验通过，实际内层是空的。","c":null},{"h":"现场 6：校验失败要返回结构化错误，而不是 500","s":"默认的校验异常如果不处理，可能返回一大段堆栈或默认错误页。凯喵：用 @RestControllerAdvice 统一捕获 MethodArgumentNotValidException，把字段名与错误信息整理成统一结构返回 400。前端…","c":{"lang":"java","code":"@ExceptionHandler(MethodArgumentNotValidException.class)\npublic ResponseEntity<?> handle(MethodArgumentNotValidException e) {\n    // 提取 field + message，返回 400\n}"}},{"h":"现场 7：全局异常处理不要吞掉异常","s":"统一异常处理里如果 catch (Exception e) { return null; }，所有错误都变成一个空响应，排查时毫无线索。凯喵：兜底处理要记日志、保留 traceId，返回给前端的是友好信息，但服务端必须留下完整堆栈。可观…","c":null},{"h":"现场 8：HTTP 状态码要用对","s":"创建成功返回 201，删除成功返回 204，参数错误 400，未认证 401，无权限 403，资源不存在 404，冲突 409。凯喵：全用 200 再在 body 里塞 code 是常见但粗糙的做法，至少要让状态码语义正确，网关、监控…","c":{"lang":"java","code":"@PostMapping(\"/users\")\n@ResponseStatus(HttpStatus.CREATED)\npublic User create(@Valid @RequestBody UserDTO dto) { ... }"}},{"h":"现场 9：DTO 与实体分离，别把数据库模型直接暴露","s":"直接把 Entity 当请求/响应体，会把密码、内部字段、懒加载代理一起暴露出去，还可能因为序列化触发额外查询。凯喵：请求用 DTO、响应用 VO，字段显式挑选，既安全又可控。这一层转换看似麻烦，却是接口稳定的关键。","c":null},{"h":"现场 10：分页参数要有上限","s":"page、size 直接透传给数据库，前端传个 size=100000 就能把服务打挂。凯喵：服务端强制上限，比如 size 最大 100，超出就截断或报错。这是最容易被忽视的「接口级限流」。","c":null},{"h":"现场 11：CORS 预检 OPTIONS 被拦截","s":"浏览器跨域先发 OPTIONS 预检，如果被登录拦截器拦掉（因为没带 token），正式请求永远发不出去。凯喵：拦截器对 OPTIONS 直接放行，或在跨域配置里正确声明允许的方法与头。这个坑只在浏览器里出现，用 Postman 测永远…","c":null},{"h":"现场 12：POST 不幂等，重试导致重复下单","s":"网络抖动时浏览器或网关会自动重试 POST，没有去重就重复执行。凯喵：用唯一请求号、去重表或资源版本号保证「同一请求多次到达得到同一结果」，或者把「创建或更新」设计成幂等的 PUT。支付、下单这类接口尤其要盯。","c":null},{"h":"现场 13：统一响应结构要早点定","s":"{ code, message, data } 这类统一结构，最好在项目初期就定下来，而不是每个接口各写各的。凯喵：统一结构让前端拦截器、错误提示、埋点统计都能复用一套逻辑；后期再改，要动所有接口和前端，成本极高。","c":{"lang":"json","code":"{ \"code\": 0, \"message\": \"ok\", \"data\": { \"id\": 1 } }"}},{"h":"现场 14：接口文档与实现要同步","s":"手写文档必然过期，凯喵推荐用注解自动生成（如 OpenAPI），让文档跟着代码走。接口字段一改，文档立刻反映，联调时少扯皮。文档不是给别人看的负担，而是接口契约的一部分。","c":null},{"h":"凯喵叮嘱：先定契约，再写实现","s":"最后叮嘱一句：写接口前先把「请求长什么样、响应长什么样、错误怎么表达」定清楚，再动手写 Controller。凯喵见过太多项目，接口写到一半才发现字段命名不统一、错误码各说各话，回头重构的成本是前期设计的好几倍。","c":null},{"h":"🧑‍💻 程序员视角","s":"@RequestBody 收 JSON 体、@RequestParam 收查询参数、@PathVariable 收路径段——三者混用是「本地能通、线上 400」的常见原因。日期与枚举的绑定要显式配 @DateTimeFormat 与 @…","c":null},{"h":"🎓 博士生视角","s":"REST 的约束（统一接口、无状态、可缓存、分层）决定了它适合「资源导向」的 API，而 RPC 风格更适合「动作导向」。Spring MVC 的处理链是「HandlerMapping → HandlerAdapter → 参数解析器…","c":null},{"h":"📚 考研者视角","s":"面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"@RestController 与 @Controller 的区别","stem":"下列关于 @RestController 与 @Controller 的说法，哪一项是正确的？","opts":[{"k":"A","t":"@RestController 比 @Controller 多了路由匹配能力，因此能处理更多请求"},{"k":"B","t":"@RestController = @Controller + @ResponseBody，方法返回值直接写响应体而非视…"},{"k":"C","t":"@Controller 不能返回 JSON，只能返回视图名"},{"k":"D","t":"两者完全等价，只是名字不同"}],"ans":"B","why":"@RestController 是 @Controller 与 @ResponseBody 的组合注解，方法返回值交给 HttpMessageConverter 直接写响应体；@Controller 默认交给 ViewResolver 解析为视图名。路由能力来自 @RequestMapping 系列，两者相同。"},{"kind":"choice","q":"@RequestParam / @PathVariable / @RequestBody 的适用场景","stem":"现有请求 POST /users/42?verbose=true，请求体是 JSON {\"name\":\"alice\"}。请问：路径里的 42、verbose、以及请求体里的 name 应分别用哪个注解接收？","opts":[{"k":"A","t":"@PathVariable、@RequestParam、@RequestBody"},{"k":"B","t":"@RequestParam、@PathVariable、@RequestBody"},{"k":"C","t":"@RequestBody、@RequestParam、@PathVariable"},{"k":"D","t":"三者都用 @RequestParam"}],"ans":"A","why":"位置决定注解：路径模板变量 /users/{id} 中的 id 用 @PathVariable；查询串 ?verbose=true 用 @RequestParam；请求体 JSON 对象用 @RequestBody。混淆会导致收不到值或 400。"},{"kind":"choice","q":"HTTP 状态码的语义选择","stem":"一个「创建用户」接口成功执行后，应返回哪个状态码最合适？","opts":[{"k":"A","t":"200 OK"},{"k":"B","t":"201 Created（并带 Location 头）"},{"k":"C","t":"204 No Content"},{"k":"D","t":"202 Accepted"}],"ans":"B","why":"创建资源成功用 201 Created，并通常带 Location 指向新资源；200 语义过泛、204 表示无内容（适合删除）、202 表示已接受异步处理尚未完成。"},{"kind":"fix_error","q":"修正「校验不生效」的代码","stem":"下面代码希望校验 UserForm 的 username 非空，但运行时校验未生效（username 为空也能通过）。请改正。 java @PostMapping(\"/users\") public ResponseEntity<?> create(UserForm form) { // 业务直接使用 form.getUsername() ... return ResponseEntity.ok()…","opts":[{"k":"A","t":"在方法参数前加 @Valid：public ResponseEntity<?> create(@Valid UserFo…"},{"k":"B","t":"在 UserForm 类上加 @Component"},{"k":"C","t":"把 @NotBlank 改成 @NotNull 即可生效"},{"k":"D","t":"在方法上加 @Transactional"}],"ans":"A","why":"Bean Validation 必须显式触发：方法参数前的 @Valid 才会让校验引擎读取字段上的约束注解并执行。只写注解而不加 @Valid 是「静默不生效」的最常见原因。"},{"kind":"output","q":"幂等性判定（PUT 重复执行）","stem":"对资源 x 依次执行下列写入序列，每次都提交相同请求： 1) PUT /res/x body={v:\"A\"} （首次） 2) PUT /res/x body={v:\"A\"} （网络重试，重复） 3) PUT /res/x body={v:\"B\"} （值变更） 问：步骤 2 执行后，资源 x 的最终状态与步骤 1 后相比是否一致？并写出「PUT 是否幂等」的结论与最终值。","opts":[],"ans":"步骤1后 x={v:A} 步骤2后 x={v:A}（与步骤1终态一致） PUT 幂等(same value)? true 最终值 x={v:B}","why":"PUT 对相同值重复执行不改变资源终态，因此幂等；只有值真正变更（步骤3）才改变终态。幂等看副作用终态，而非响应体是否相同。"},{"kind":"choice","q":"全局异常处理的映射","stem":"使用 @ControllerAdvice + @ExceptionHandler 做统一异常处理。对于「业务上资源不存在」抛出的 ResourceNotFoundException，最合适的状态码是？","opts":[{"k":"A","t":"400 Bad Request"},{"k":"B","t":"404 Not Found"},{"k":"C","t":"500 Internal Server Error"},{"k":"D","t":"200 OK + 错误体"}],"ans":"B","why":"异常类型应映射到语义正确的状态码：资源不存在→404；未认证→401；无权限→403；业务冲突→409；未捕获运行时异常兜底 500。不要用 200 包错误体。"},{"kind":"coding","q":"实现路径变量提取算法","stem":"给定路由模板（如 /users/{id}/posts/{pid}）与真实请求路径（如 /users/7/posts/99），实现 match 方法提取路径变量；若段数不同或非模板段字面值不匹配则返回 null。要求时间复杂度 O(n)（n 为路径段数）。","opts":[],"ans":"import java.util.; public class Main { // 返回 LinkedHashMap 保证插入顺序；不匹配返回 null static Map<String,String> match(String template, String path){ String[] tp = templa…","why":"逐段比较：模板段若为 {name} 则捕获真实段；否则要求字面值相等；段数不等直接不匹配。一次线性扫描即完成，复杂度 O(n)。这正是 Web 框架路径匹配的最小内核。"},{"kind":"choice","q":"LeetCode 146 LRU 缓存（幂等请求结果缓存）","stem":"本题为 LeetCode 原题，本条目仅存元数据与链接，不搬运题面正文。它常用于考查「用 LRU 缓存幂等请求/限流计数结果」的工程能力：容量满时淘汰最久未使用项，get/put 均 O(1)。","opts":[{"k":"A","t":"哈希表 + 双向链表的 O(1) 实现"},{"k":"B","t":"仅用数组顺序查找"},{"k":"C","t":"用优先队列按时间戳排序"},{"k":"D","t":"递归实现"}],"ans":"A","why":"标准解法是哈希表定位 + 双向链表维护最近使用顺序，使 get/put 均为 O(1)；常用于缓存幂等请求的响应（key=请求指纹）。详见原题链接，题面不在此搬运。"}],"works":[{"h":"@RestController 与 @Controller 混用，返回 JSON 变成视图名…","d":"在普通 @Controller 方法里直接 return \"ok\"，Spring 会拿它当视图名去解析，前端收到的是一段 HTML 而非 JSON。正确写法：要么类上用 @RestController，要么在方法上加 @ResponseBody；返回对象让消息转换器序列化。"},{"h":"@RequestParam 默认 required=true，缺参会直接 400 而非拿到…","d":"很多「参数收不到就 400」的诡异现象源于此。正确写法：可选参数显式 required = false，或用 defaultValue；真正可空的字段就别依赖隐式 null。"},{"h":"@PathVariable 与 @RequestParam 混淆","d":"把 /users/{id} 里的 id 用 @RequestParam 取，结果永远收不到；或反过来把查询串 ?id=1 当路径变量取。正确写法：路径模板变量用 @PathVariable，查询串/表单用 @RequestParam，位置决定注解。"},{"h":"@RequestBody 只能读一次，拦截器/过滤器读过流后 Controller 收空体","d":"在 Filter/Interceptor 里为了打日志读了 request.getInputStream()，后续 Spring 读到的就是空。正确写法：用 ContentCachingRequestWrapper 缓存请求体，或把读体逻辑放到最里层只读取一次。"},{"h":"GET 请求带 @RequestBody 被服务器/客户端拒绝","d":"HTTP 语义上 GET 不应带请求体，部分容器直接忽略或报错，导致参数永远为空。正确写法：查询用 @RequestParam/路径变量；需要传复杂结构时用 POST/PUT。"},{"h":"忘记加 @Valid，@NotNull/@Size 校验「静默不生效」","d":"注解贴了但方法参数前没写 @Valid（或类上没 @Validated），校验引擎根本不触发。正确写法：Controller 方法参数前加 @Valid，且校验失败要配 @ExceptionHandler 转成 400/422，而不是让它冒泡成 500。"},{"h":"分组校验只在一边写了 groups","d":"字段标了 @NotNull(groups = Update.class)，方法上却没 @Validated(Update.class)，结果该约束永不执行，「看起来没生效」。正确写法：groups 在字段和方法上两边都要声明；不声明组的约束只在 Default 组生效。"},{"h":"直接 return map/ResponseEntity 却手写 JSON 字符串","d":"绕过消息转换器手动拼 \"{\\\"a\\\":1}\"，既失去内容协商能力（永远只能 JSON），又容易因拼接引入 XSS/注入。正确写法：返回对象或 ResponseEntity<T>，让 Jackson 统一序列化。"}],"asks":[{"q":"@RestController 和 @Controller 的区别？什么时候用哪个？","a":"@RestController = @Controller + @ResponseBody。前者每个方法默认把返回值交给 HttpMessageConverter 直接写响应体（适合 JSON API）；后者默认把返回值交给 ViewResolver 解析为视图名（适合服务端渲染页面），若想返回数据需在方法上加 @ResponseBody。 路由能力二者相同，都来自 @RequestMapping…","fu":["@ResponseBody 在底层是怎么生效的？","一个类里能部分方法返回视图、部分返回 JSON 吗？"],"tag":"通用/阿里"},{"q":"@RequestParam、@PathVariable、@RequestBody 的区别与适用场景？","a":"三者吃不同的请求位置： - @RequestParam：查询串或表单字段（?page=2&size=10），默认 required=true； - @PathVariable：路径模板变量（/users/{id} 里的 id）； - @RequestBody：整个请求体（通常 JSON），由消息转换器反序列化。 位置决定注解，混淆会导致收不到值或 400。注意 @RequestBody 只能读一次…","fu":["@RequestBody 在拦截器读过流后为什么收空？","同名多值怎么用 List 接收？"],"tag":"通用/美团"},{"q":"Spring MVC 处理一个请求的整体流程是怎样的？","a":"核心在 DispatcherServlet： 1. 收到请求，由 HandlerMapping（实际是 RequestMappingHandlerMapping）按「请求条件」找到 HandlerMethod； 2. HandlerAdapter 调用目标方法，期间 HttpMessageConverter 完成 @RequestBody 反序列化、@ResponseBody 序列化； 3. 若声…","fu":["HandlerMapping 和 HandlerAdapter 各自负责什么？","拦截器 Interceptor 在流程的哪一步执行？"],"tag":"通用/字节"},{"q":"Bean Validation 是怎么工作的？为什么有时「加了注解却不生效」？","a":"约束注解（如 @NotNull）是元数据，逻辑在 ConstraintValidator<A,T> 实现里。校验引擎通过反射读取字段注解并调用对应验证器，把 ConstraintViolation 收集进 Set（validate() 收集全部违反项）。 不生效的根因：校验必须显式触发——Controller 方法参数前缺 @Valid（或类上缺 @Validated），引擎不会执行。分组校验还要…","fu":["@Valid 和 @Validated 的区别？","怎么收集所有校验错误一次性返回？"],"tag":"通用/阿里"}]},{"id":"spring-ch06","subj":"spring","title":"MyBatis 基础：映射与 CRUD","summary":"半自动 ORM 的定位；SqlSession 与 Mapper 接口的动态代理绑定；#{} 预编译与 ${} 字符串拼接的 SQL 注入差异；resultMap、驼峰映射与关联映射；主键回填与 useGeneratedKeys；与原生 JD…","concepts":[{"id":"spring-ch06/01-orm-positioning-and-mapper","file":"01-orm-positioning-and-mapper.md","title":"一、MyBatis 定位与 Mapper 绑定","kind":"compare","secs":[{"h":"1. 半自动 ORM 的定位与 SqlSession / Mapper 动态代理","s":"MyBatis 是「半自动」持久层框架：程序员写 SQL，框架负责参数绑定与结果映射，","c":null},{"h":"2. 与 JDBC / JPA 的取舍","s":"直接用 JDBC：SQL 与 Java 代码耦合、手动 ResultSet→对象、样板代码多（90% 是 try/catch/close），MyBatis 消除这些样板。JPA 适合 CRUD 重、查询简单的领域，但复杂 join/统计…","c":null},{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"import xml.etree.ElementTree as ET\nimport re\n\nXML = \"\"\"<mapper namespace=\"com.demo.UserMapper\">\n  <select id=\"selectById\" resultType=\"User\">\n    SELECT id, user_name, age FROM t_user WHERE id = #{id}\n  </select>\n  <insert id=\"insertUser\" useGeneratedKeys=\"true\" keyProperty=\"id\">\n    INSERT INTO t_user(user_name, age) VALUES(#{name}, #{age})\n…"}}]},{"id":"spring-ch06/02-placeholder-and-injection","file":"02-placeholder-and-injection.md","title":"二、#{} 预编译与 ${} 拼接：SQL 注入的分水岭","kind":"compare","secs":[{"h":"1. #{} 与 ${} 的语义差异","s":"#{} 在 MyBatis 里被替换成 JDBC 的 ? 占位符，参数通过 PreparedStatement 单独绑定（预编译）；","c":null},{"h":"2. PreparedStatement 预编译原理","s":"#{} 在底层被翻译成 JDBC 的 PreparedStatement：带 ? 的 SQL 先 prepare，之后只 execute 并绑定参数。","c":null},{"h":"可运行代码：${} 与 #{} 的区别","s":"两种花括号经常被混用：${} 取配置值（占位符替换，发生在容器启动期），","c":{"lang":"java","code":"@Component\npublic class RetryConfig {\n\n    @Value(\"${app.retry.max:3}\")            // 冒号后是默认值：配置缺失也不报错\n    private int max;\n\n    @Value(\"${app.retry.delay-ms:200}\")\n    private long delayMs;\n\n…"}}]},{"id":"spring-ch06/03-resultmap-and-camel","file":"03-resultmap-and-camel.md","title":"三、resultMap、驼峰映射与关联映射","kind":"flow","secs":[{"h":"1. resultMap：列→字段映射与何时必须手写","s":"resultType 让 MyBatis 自动按「属性名=列名（或驼峰）」映射；resultMap 是显式映射声明，","c":null},{"h":"2. 驼峰映射与关联映射","s":"开启 mapUnderscoreToCamelCase 后，user_name 自动映射到 userName，省去大量手写 resultMap。","c":null}]},{"id":"spring-ch06/04-key-generation-and-config","file":"04-key-generation-and-config.md","title":"四、主键回填与 XML/注解配置","kind":"compare","secs":[{"h":"1. 主键回填：useGeneratedKeys 与 selectKey","s":"插入后数据库自增主键需要回填到实体。MyBatis 提供 useGeneratedKeys + keyProperty（数据库自增）","c":null},{"h":"2. XML 映射 vs 注解：两种写法归一","s":"SQL 可写在 XML（<mapper>）或接口注解（@Select 等）上。两种方式在解析后归一为同一份 MappedStatement 元数据。","c":null}]},{"id":"spring-ch06/05-mybatis-practical-recipes","file":"05-mybatis-practical-recipes.md","title":"MyBatis 实战手记：凯喵被 ${} 坑掉一个库的十二个现场","kind":"flow","secs":[{"h":"开场：MyBatis 是\"半自动\"的 ORM，这个定位决定了它的全部性格","s":"JPA/Hibernate 是\"全自动\"：你写实体和注解，SQL 由框架生成。MyBatis 是\"半自动\"：SQL 由你写，映射由框架做。","c":{"lang":"xml","code":"<!-- 危险写法 -->\n<select id=\"findByName\" resultType=\"User\">\n    SELECT * FROM users WHERE name = '${name}'\n</select>"}},{"h":"收尾：凯喵的 MyBatis 五条铁律","s":"最后说一句方法上的话。MyBatis 的坑有个共同特征：它们都不会在启动时报错，只会在某个特定数据、特定并发、特定配置下悄悄出错。${} 平时跑得好好的，直到有人输入了单引号；驼峰没开时字段全 null，但接口不报错；一级缓存读到旧值…","c":{"lang":"java","code":"@Component\npublic class MyBatisConfigPrinter implements ApplicationRunner {\n    private final SqlSessionFactory factory;\n    public MyBatisConfigPrinter(SqlSessionFactory factory) { this.factory = factory; }\n\n    @Override\n    public void run(ApplicationArguments args) {\n        var c = factory.getConfiguration();\n        log.info(\"mapUnderscoreToCamelCase = {}\", c.isMapUnderscoreToCamelCase());\n…"}}]}],"exams":[{"kind":"choice","q":"#{} 与 ${} 的区别","stem":"下列关于 MyBatis 中 #{} 与 ${} 的说法，哪一项是正确的？","opts":[{"k":"A","t":"${} 会被替换成 ? 占位符并预编译，#{} 是直接字符串拼接"},{"k":"B","t":"#{} 被替换成 ? 占位符，参数经 PreparedStatement 预编译绑定，可防 SQL 注入；${} 是直接…"},{"k":"C","t":"#{} 与 ${} 只是写法不同，底层完全等价"},{"k":"D","t":"只有 ${} 能防 SQL 注入，#{} 不能"}],"ans":"B","why":"#{} 在解析阶段被替换成 JDBC 的 ? 占位符，参数通过 PreparedStatement 单独绑定（预编译），数据库区分代码与数据，因此防注入；${} 是文本插值，把值直接拼进 SQL 文本，存在注入风险，仅用于表名/列名/排序等非值场景。"},{"kind":"choice","q":"resultType 与 resultMap 的区别","stem":"下列关于 resultType 与 resultMap 的说法，正确的是？","opts":[{"k":"A","t":"resultMap 比 resultType 更快，应该一律用 resultMap"},{"k":"B","t":"resultType 靠自动映射（同名/驼峰），简单快捷；resultMap 显式声明列-字段映射，支持别名、嵌套、关联…"},{"k":"C","t":"列名与属性名不一致时，开驼峰也查不出，必须用 JDBC 改名"},{"k":"D","t":"resultType 无法使用，MyBatis 只支持 resultMap"}],"ans":"B","why":"resultType 依赖自动映射（同名或驼峰），适合简单 CRUD；resultMap 显式声明 column→property 映射，支持嵌套对象与关联（association/collection），用于处理列名不一致与复杂结果。简单场景手写 resultMap 是过度设计。"},{"kind":"choice","q":"#{} 防 SQL 注入的底层原理","stem":"为什么 #{} 能防止 SQL 注入？最准确的一项是？","opts":[{"k":"A","t":"MyBatis 对参数做了单引号转义，所以注入失效"},{"k":"B","t":"#{} 被替换成 ? 占位符，SQL 模板先预编译，参数作为数据单独绑定，数据库区分指令与数据"},{"k":"C","t":"#{} 会自动过滤掉 OR 和单引号等关键字"},{"k":"D","t":"因为 MyBatis 默认开启了防火墙"}],"ans":"B","why":"核心机制是参数化查询（预编译）：带 ? 的 SQL 先发给数据库编译成执行计划，参数在 setXxx 阶段作为数据传入，数据库无法把数据当 SQL 指令执行。转义单引号是黑名单思维，预编译是白名单（结构固定、参数只是数据），更彻底。"},{"kind":"choice","q":"一级缓存与二级缓存的范围","stem":"关于 MyBatis 一级缓存与二级缓存的范围，正确的是？","opts":[{"k":"A","t":"一级缓存是 namespace 级，跨 SqlSession 共享"},{"k":"B","t":"一级缓存是 SqlSession 级，同一会话内相同查询命中；二级缓存是 namespace（Mapper）级，跨 Sq…"},{"k":"C","t":"二级缓存默认开启，无需任何配置"},{"k":"D","t":"一级缓存在 SqlSession 关闭后依然存在"}],"ans":"B","why":"一级缓存（local cache）默认开启，作用域是 SqlSession，同一会话内相同查询命中；二级缓存作用域是 Mapper 的 namespace，跨 SqlSession 共享，需显式 <cache/> 开启且缓存对象需可序列化；SqlSession 关闭/提交后一级缓存清空或晋升二级。"},{"kind":"fix_error","q":"修正「驼峰未开导致字段为 null」","stem":"实体属性名为 userName，数据库列为 user_name。查询使用 resultType 且未做任何映射配置，结果 userName 为 null。下列哪种改法能解决问题？","opts":[{"k":"A","t":"把数据库列改名为 userName"},{"k":"B","t":"把实体属性改名为 user_name"},{"k":"C","t":"在全局配置开启 mapUnderscoreToCamelCase=true"},{"k":"D","t":"C（开驼峰）或手写 resultMap 显式映射 user_name→userName 均可"}],"ans":"D","why":"列名与属性名不一致时，要么开 mapUnderscoreToCamelCase 让下划线自动转驼峰，要么手写 resultMap 显式声明 column→property。两者都能解决；改列名/属性名通常不可行（受既有库表或领域模型约束）。"},{"kind":"choice","q":"插入后如何拿到自增主键","stem":"向自增主键表插入一行后，如何正确获取数据库生成的主键？","opts":[{"k":"A","t":"insert 语句的返回值就是主键"},{"k":"B","t":"用 useGeneratedKeys=true 且 keyProperty 指定属性，插入后从传入实体对象取回主键；in…"},{"k":"C","t":"必须再发一条 SELECT MAX(id) 查询"},{"k":"D","t":"主键只能通过数据库序列获取"}],"ans":"B","why":"insert 返回的是受影响行数，不是主键。需配置 useGeneratedKeys=true 与 keyProperty=属性名，MyBatis 通过 JDBC getGeneratedKeys 把生成的主键回填到传入实体；Oracle 无自增列需用 <selectKey order=BEFORE> 取序列。"},{"kind":"coding","q":"实现下划线命名转小驼峰","stem":"实现 to_camel(name)：把下划线命名（如 user_name）转换为小驼峰（如 userName）。要求 O(n) 且正确处理多段（如 create_time → createTime）。","opts":[],"ans":"def to_camel(name): parts = name.split(\"_\") return parts[0] + \"\".join(p.capitalize() for p in parts[1:]) if __name__ == \"__main__\": print(to_camel(\"user_name\"))…","why":"按 _ 切词，首段保留原样，其余每段首字母大写后拼接。这正是 MyBatis 驼峰映射的确定性变换函数。时间复杂度 O(n)（n 为字符串长度）。"},{"kind":"choice","q":"LeetCode 175 Combine Two Tables（关联映射思想）","stem":"本题为 LeetCode 原题，本条目仅存元数据与链接，不搬运题面正文。它常用于考查「关系表 LEFT JOIN 与结果投影」——这正是 MyBatis 用 resultMap/关联把多表行装配成对象图的思想来源：用 Person 的 id 关联 Address，缺失地址时地址字段为 null（对应嵌套对象为 null）。","opts":[{"k":"A","t":"用 LEFT JOIN 保留左表全部行，右表缺失列补 null"},{"k":"B","t":"用 INNER JOIN 只保留两表都匹配的行"},{"k":"C","t":"用 CROSS JOIN 笛卡尔积"},{"k":"D","t":"用 UNION 纵向拼接"}],"ans":"A","why":"标准解法是 LEFT JOIN：保证左表（Person）每一行都出现，右表（Address）无匹配时对应列为 null——对应 MyBatis 关联映射里「嵌套对象可能为 null」的语义。详见原题链接，题面不在此搬运。"}],"works":[{"h":"用 ${} 拼接前端字符串导致 SQL 注入","d":"任何来自用户的文本若经 ${} 拼进 SQL，会被当 SQL 执行（如 name = ${name} 输入 ' OR '1'='1 把全表拖出）。正确写法：值是 #{} 占位符；只有表名/列名/排序字段这类不能作为占位符的才用 ${}，且 ${} 的取值必须来自白名单。"},{"h":"列名与属性名不一致又没开驼峰也没写 resultMap，字段查出 null","d":"数据库 user_name，实体 userName，既没开 mapUnderscoreToCamelCase 也没写 <result>，MyBatis 自动映射按同名匹配失败。正确写法：开驼峰，或用 resultMap 显式 <result column=\"user_name\" property=\"userName\"/>。"},{"h":"把 insert 返回值当主键","d":"insert 返回的是受影响行数（int），不是主键。正确写法：用 useGeneratedKeys=\"true\" keyProperty=\"id\"，插入后从传入实体对象 user.getId() 取回自增主键。"},{"h":"在 Oracle 上用 useGeneratedKeys 期望自增","d":"Oracle 没有自增列，useGeneratedKeys 对其无效。正确写法：用 <selectKey order=\"BEFORE\" keyProperty=\"id\">SELECT seq.nextval FROM dual</selectKey> 先取序列号再插入。"},{"h":"以为没开驼峰也会自动映射下划线","d":"默认是「属性名 = 列名」严格同名，user_name 不会自动变成 userName。正确写法：显式开启 mapUnderscoreToCamelCase=true，或手写 resultMap。"},{"h":"resultMap 里两表同名列（id）互相覆盖","d":"主表 id 与关联表 id 都映射到属性 id，后者覆盖前者，关联结果错乱。正确写法：用 <id column=\"u_id\" property=\"userId\"/> 给关联列起别名，或用 resultMap 的 columnPrefix。"},{"h":"嵌套查询 <association select=...> 触发 N+1 却以为是一次查询","d":"1 次主查询 + 每行 1 次子查询 = N+1 次 SQL。正确写法：用嵌套结果（<collection> 一次 join 查出并按父 id 分组），或开启延迟加载并评估是否真的需要。"},{"h":"#{} 传 null 没给 jdbcType 导致部分驱动报错","d":"某些 JDBC 驱动（尤其 Oracle）对 null 参数需要类型提示。正确写法：写成 #{val,jdbcType=VARCHAR}，显式告知列类型。"}],"asks":[{"q":"#{} 和 ${} 的区别？为什么 #{} 能防 SQL 注入？","a":"#{} 被 MyBatis 替换成 JDBC 的 ? 占位符，参数通过 PreparedStatement 预编译后单独绑定，数据库区分 SQL 指令与数据，特殊字符只当作字段值，因此防注入。 ${} 是纯文本字符串拼接，把值直接拼进 SQL 文本后再提交，数据库无法区分代码与数据，来自前端的输入会被当 SQL 执行，存在注入风险。 使用边界：值是 #{}；只有表名、列名、排序字段等不能作为占位符…","fu":["PreparedStatement 预编译在协议层是怎么实现的？","MyBatis 日志里怎么一眼看出哪里用了 ${}？"],"tag":"通用/阿里"},{"q":"resultType 和 resultMap 的区别？什么时候必须手写 resultMap？","a":"resultType 依赖自动映射（属性名=列名，或开驼峰后下划线转驼峰），简单快捷；resultMap 显式声明 column→property 映射，支持别名、嵌套对象与关联（association/collection）。 必须手写 resultMap 的场景：列名与属性名不一致又没开驼峰、一对多/多对一关联、继承/discriminator、构造器注入。简单 CRUD 用 resultTy…","fu":["关联映射为什么容易触发 N+1？怎么优化？","两表都有 id 列时 resultMap 怎么避免覆盖？"],"tag":"通用/美团"},{"q":"MyBatis 的一级缓存和二级缓存分别是什么范围？有什么坑？","a":"一级缓存（local cache）默认开启，作用域是 SqlSession，同一会话内相同查询命中缓存；SqlSession 关闭/提交后清空或晋升二级。 二级缓存作用域是 Mapper 的 namespace，跨 SqlSession 共享，需显式 <cache/> 开启且缓存对象需可序列化。 坑：一级缓存下若绕过 MyBatis 直连 JDBC 改库，会话内会读到旧值；二级缓存返回的是对象引用…","fu":["一级缓存在什么情况下会失效？","二级缓存为什么要求对象可序列化？"],"tag":"通用/蚂蚁"},{"q":"MyBatis 的动态 SQL 有哪些常用标签？各自解决什么？","a":"常用标签：<if>（按条件拼接片段）、<choose>/<when>/<otherwise>（多选一，等价于 switch）、<foreach>（遍历集合做 IN 或批量插入）、<where>（智能加 WHERE 并去除前缀 AND/OR）、<set>（智能加 SET 并去除尾部逗号）、<trim>（通用修剪）、<sql>/<include>（片段复用）。 它们本质是「带条件的 SQL 文本拼接」…","fu":["<where> 是怎么去掉前缀 AND 的？","<foreach> 的 collection 在不同参数类型下叫什么？"],"tag":"通用/百度"}]},{"id":"spring-ch07","subj":"spring","title":"MyBatis 进阶：动态 SQL、缓存与插件","summary":"<if>/<choose>/<foreach>/<trim> 动态 SQL 与 <sql> 片段复用；一级缓存（SqlSession 级）与二级缓存（namespace 级）的失效条件与陷阱；延迟加载；分页插件的拦截器原理（改写 SQL）…","concepts":[{"id":"spring-ch07/01-dynamic-sql-tags","file":"01-dynamic-sql-tags.md","title":"一、动态 SQL：把拼接交给标签，把安全留给占位符","kind":"flow","secs":[{"h":"一、条件标签：<if> 与 <choose>","s":"<if test=\"...\"> 的 test 是 OGNL 表达式，不是 Java 表达式，也不是 EL。","c":{"lang":"markdown","code":"<select id=\"search\" resultType=\"User\">\n  SELECT id, name FROM t_user\n  <where>\n    <if test=\"name != null and name != ''\"> AND name = #{name} </if>\n    <choose>\n      <when test=\"type eq 'A'\"> AND status = 0 </when>\n      <when test=\"type eq 'B'\"> AND status = 1 </when>\n      <otherwise> AND 1 = 1 </otherwise>\n    </choose>\n…"}},{"h":"二、智能修剪：<where> / <set> / <trim>","s":"这三个标签解决的是拼接产生的不合法片段问题：悬空的前导 AND、多余的尾部逗号、","c":{"lang":"text","code":"原始拼接结果        <where> 处理结果\n------------------  ------------------\n\"AND status = ?\"    \"WHERE status = ?\"\n\"AND name = ? AND status = ?\"  \"WHERE name = ? AND status = ?\"\n\"\"                  \"\"              <-- 整条子句消失，没有悬空的 WHERE"}},{"h":"三、片段复用：<sql> / <include> / <property>","s":"<sql id=\"baseColumns\">id, name, age</sql> 定义片段，","c":{"lang":"text","code":"<sql id=\"cols\">${alias}.id, ${alias}.name</sql>\n\n<include refid=\"cols\"><property name=\"alias\" value=\"u\"/></include>   ->  u.id, u.name\n<include refid=\"cols\"><property name=\"alias\" value=\"t\"/></include>   ->  t.id, t.name\n<include refid=\"cols\"/>                                              ->  ${alias}.id, ${alias}.name"}}]},{"id":"spring-ch07/02-hash-vs-dollar-deep","file":"02-hash-vs-dollar-deep.md","title":"二、#{} 与 ${}：从解析管线到注入利用链","kind":"compare","secs":[{"h":"一、两条路径的形式差异：ParameterMapping + TypeHandler vs…","s":"#{} 的完整语法是 #{property, javaType=int, jdbcType=NUMERIC, typeHandler=XxxTypeHandler, mode=IN}，","c":{"lang":"java","code":"// 反面：黑名单式过滤（'--'、';' 、' or ' 之类），永远漏\nString col = req.getColumn();\nif (col.contains(\";\") || col.contains(\"--\")) throw new IllegalArgumentException();\n\n// 正面：白名单，只允许枚举里存在的列名\nprivate static final Set<String> SORTABLE = Set.of(\"id\", \"create_time\", \"amount\");\nif (!SORTABLE.contains(sortColumn)) throw new IllegalArgumentException(\"illegal sort column\");"}},{"h":"二、注入利用链：从「拼进去」到「改语义」","s":"注入的本质是让输入参与语法分析。${} 把输入拼进文本，输入于是被当代码解析。","c":{"lang":"text","code":"模板：  SELECT * FROM t_user WHERE name = '${name}'\n输入：  ' OR '1'='1\n结果：  SELECT * FROM t_user WHERE name = '' OR '1'='1'\n                                      ^^^^^^^^^^^^^^^ 新增了一个恒真析取项"}},{"h":"三、与 JDBC 协议的边界：预编译到底预编译了什么","s":"#{} 并非必然带来「服务端预编译」。是否真预编译取决于驱动与连接参数：","c":{"lang":"java","code":"// #{} -> PreparedStatement 的 ?，参数走二进制协议，永不参与 SQL 解析\nString sql = \"SELECT * FROM t_user WHERE name = ?\";\ntry (PreparedStatement ps = conn.prepareStatement(sql)) {\n    ps.setString(1, userInput);     // 传 \"a' OR '1'='1\" 也只是个字符串\n    try (ResultSet rs = ps.executeQuery()) { /* ... */ }\n}\n\n// ${} -> 字符串拼接，参数直接改写 SQL 语义\nString bad = \"SELECT * FROM \" + tableName + \" WHERE id = ?\";"}}]},{"id":"spring-ch07/03-cache-l1-l2","file":"03-cache-l1-l2.md","title":"三、缓存体系：一级 / 二级的作用域、失效与陷阱","kind":"flow","secs":[{"h":"一、一级缓存：SqlSession 级，Key 由四元组决定","s":"一级缓存的 Key 是 CacheKey，由四部分拼成：statementId + offset（分页 offset）+","c":null},{"h":"二、二级缓存：namespace 级，提交后才可见","s":"开启方式是在 Mapper XML 里写 <cache/>（或在接口上 @CacheNamespace）。","c":null},{"h":"三、缓存陷阱实战：四类症状与定位口径","s":"若现象消失则确诊）；","c":{"lang":"java","code":"// 同一个 SqlSession 内，两条完全相同的查询只发一次 SQL\ntry (SqlSession s = sqlSessionFactory.openSession()) {\n    UserMapper m = s.getMapper(UserMapper.class);\n    m.selectById(1L);   // 发 SQL\n    m.selectById(1L);   // 命中一级缓存，不发 SQL\n}"}}]}],"exams":[{"kind":"choice","q":"<where> 的三条保证：哪一项是错的","stem":"关于 MyBatis 的 <where> 标签，业界总结的四条说法中有一条是错的，请选出来。 - A. 内部所有条件都不成立时，<where> 整体不生成 WHERE 关键字 - B. 内部有内容时，自动加上 WHERE 并剔除片段开头多余的 AND / OR - C. 它等价于 <trim prefix=\"WHERE\" prefixOverrides=\"AND |OR \"> - D. 它会同时剔…","opts":[{"k":"A","t":"内部所有条件都不成立时，整体不生成 WHERE 关键字"},{"k":"B","t":"有内容时自动加 WHERE 并剔除开头多余的 AND / OR"},{"k":"C","t":"等价于 <trim prefix=\"WHERE\" prefixOverrides=\"AND |OR \">"},{"k":"D","t":"会同时剔除片段中间重复出现的 AND"}],"ans":"D","why":"D 错。TrimSqlNode 的算法是「先拼完整串、再只剪首尾」： startsWith(override) 命中则 substring(length)，尾部由 suffixOverrides 回退，因此 4=4 AND AND name = ? 这种中间残留它管不了（中间多写了 AND 只能靠把每个条件的 AND 写在片段开头来保证局部性）。A/B 是 <where> 的两…"},{"kind":"fix_error","q":"修掉一段会被注入的排序查询","stem":"下面是某列表接口的 Mapper 片段与调用代码，至少有三处问题： xml <select id=\"list\" resultType=\"User\"> SELECT id, name FROM t_user WHERE name = '${name}' ORDER BY ${sortCol} ${sortDir} </select> java // Controller 直接透传前端参数 mappe…","opts":[],"ans":"① WHERE name = '${name}' 是宏替换，输入 ' OR '1'='1 即可拖走全表 —— 改为 name = #{name}； ② ORDER BY ${sortCol} / ${sortDir} 来自前端原始字符串，可借子查询做布尔盲注/时间盲注 —— 结构性位置只能靠白名单兜底，不能因为「只是排…","why":"判据是「该位置在 SQL 语法里是值还是结构」：值（WHERE 的比较值、LIMIT 的参数）用 #{}， 此时 SQL 模板不随参数变化，参数经 PreparedStatement 单独绑定； 结构位置（列名、排序方向）不能参数化，只能用 ${} + 白名单枚举。黑名单式过滤（;/-- 替换）会因宽字节、注释变体、大小写绕过。另一条常被同时踩到的坑是反过来写成 ORDER B…"},{"kind":"choice","q":"<foreach> 传入空集合会发生什么","stem":"Mapper 中写： xml <select id=\"findByIds\" resultType=\"User\"> SELECT id, name FROM t_user WHERE id IN <foreach collection=\"ids\" item=\"id\" open=\"(\" separator=\",\" close=\")\"> #{id} </foreach> </select> 调用时传入…","opts":[{"k":"A","t":"自动展开成 IN (NULL)，查询正常执行但返回 0 行"},{"k":"B","t":"<foreach> 不产出任何内容，最终 SQL 是 ... WHERE id IN ()，MySQL 直接报语法错误"},{"k":"C","t":"外层的 <where> 会识别到空的 IN 子句并自动整条剔除"},{"k":"D","t":"MyBatis 在参数绑定阶段抛 BindingException 拦截下来"}],"ans":"B","why":"<foreach> 只负责把集合展开成占位符列表，不提供空集合保护：open=\"(\" close=\")\" 属于 <foreach> 自身的常量，无论集合是否为空都会输出，于是得到 ... WHERE id IN () —— MySQL 报 You have an error in your SQL syntax（见 ex02 的 empty IN : SELECT FROM t…"},{"kind":"choice","q":"一级缓存的失效触发点","stem":"在同一个 SqlSession 内（在 Spring 中即同一个事务内），下列哪种操作不会让一级缓存失效？","opts":[{"k":"A","t":"在会话内执行任意一条 insert / update / delete（哪怕写的表与本次查询无关）"},{"k":"B","t":"调用 sqlSession.commit() 或 rollback()"},{"k":"C","t":"在会话内再执行一次相同 statementId + 相同 SQL + 相同参数的查询"},{"k":"D","t":"该语句上配置了 flushCache=\"true\""}],"ans":"C","why":"C 是命中路径而不是失效路径：CacheKey 由 statementId + offset + limit + SQL 文本 + 参数列表构成，三者相同即命中（见 ex06 的 s1 select#2 : dbQueries=1 l1Hits=1）。另外三项都会失效：写操作走 BaseExecutor.update() → clearLocalCache()，清空的是整个会话…"},{"kind":"output","q":"二级缓存 namespace 隔离：写出三次查询的命中情况","stem":"UserMapper 与 OrderMapper 都在各自的 Mapper XML 里声明了 <cache/>， 按下列顺序执行（每行一次独立会话，会话结束前都提交）： text ① s1 SELECT UserMapper.selectById(1) -> 查库 ② s2 SELECT UserMapper.selectById(1) -> ? ③ s3 UPDATE OrderMapper.u…","opts":[],"ans":"② l2hit=1 db=0 -> 命中 UserMapper 的二级缓存，未查库 ④ l2hit=1 db=0 -> 依然命中 UserMapper 的二级缓存，未查库 最终读到 -> 旧值（脏读）","why":"二级缓存的作用域是 Mapper namespace，失效协议是「谁拥有 namespace，谁负责清」：OrderMapper.updateUser 只会 flush OrderMapper 自己的缓存，UserMapper 的缓存条目完好无损，于是 s4 读到的是 s3 更新之前的旧值。这正是 ex07 里 s6 OrderMapper : db=4 l2=1 (unaff…"},{"kind":"choice","q":"分页插件：startPage 的生效范围与 count 改写","stem":"关于 MyBatis 分页插件（以 PageHelper 为代表）的 count 查询与生效范围，哪一项说法是正确的？","opts":[{"k":"A","t":"startPage() 调用后对本次线程随后执行的所有查询都生效，中间穿插其他 mapper 调用也不影响"},{"k":"B","t":"startPage() 依赖 ThreadLocal 传递分页参数，只对紧随其后的那一次查询生效，中间插入别的查询会让分…"},{"k":"C","t":"count 查询一定是对原 SQL 的 select 列直接替换成 count(0)，所以原 SQL 带有 ORDER…"},{"k":"D","t":"对带有 GROUP BY 的原 SQL，直接把列换成 count(0) 得到的就是正确的总记录数"}],"ans":"B","why":"B 正确。startPage() 把分页参数放在 ThreadLocal 里，拦截器在下一次 StatementHandler#prepare 处消费它，而它只对「紧随其后」的那一次查询才生效—— 所以调用必须与目标 mapper 查询紧邻（同一方法内、中间不插其他查询）， 中间只要多一次查询就会被提前消费；线程池复用线程时还可能带上一次请求的残余参数，因此规范的写法要在 fi…"},{"kind":"coding","q":"LRU 缓存（LeetCode 146）","stem":"到 LeetCode 上完成第 146 题「LRU 缓存」。 合规说明：本节只保留题目的元数据与链接，不搬运题面正文，请通过下方链接查看完整题面。 完成要求：get 与 put 均为 O(1)；容量满时淘汰最久未使用的键。 与本章的关联：MyBatis LruCache 正是用 LinkedHashMap 的访问顺序（access-order）记录热度、并在超过 size 时淘汰链头元素，思路与手…","opts":[],"ans":"from collections import OrderedDict class LRUCache: \"\"\"哈希表 + 双向链表：这里直接用 OrderedDict 承担链表角色。 MyBatis 的 LruCache 用的就是同一套 access-order 语义。 \"\"\" def __init__(self, c…","why":"get 命中后把节点移到链尾（最近使用），put 超容量时弹出链头（最久未使用），两个操作都是 O(1)——这是「哈希表 + 双向链表」的经典配对：哈希表负责定位，链表负责维护顺序。MyBatis 的二级缓存默认 eviction=\"LRU\" 即 LruCache 装饰 PerpetualCache，内部就是一个 access-order 的 LinkedHashMap，超过…"},{"kind":"coding","q":"实现带 namespace 隔离的 LRU 二级缓存","stem":"用纯 Python 单文件实现一个简化的 MyBatis 二级缓存，要求： 1. 按 namespace 隔离：UserMapper 与 OrderMapper 各有一份 LRU，互不可见； 2. 容量上限：每个 namespace 的容量为 size，超过时淘汰最久未使用的 key； 3. 写操作只失效本 namespace：对某 namespace 执行 update 后，该 namespac…","opts":[],"ans":"from collections import OrderedDict class NamespaceLRU: \"\"\"单个 namespace 一份 access-order LRU。\"\"\" def __init__(self, size: int = 3): self.size = size self.data: O…","why":"两条授课要点都在代码里：(1) update(ns) 只清自身 namespace，所以当有多方写同一张表时，缓存就出现了失效覆盖缺口——无论是 MyBatis 还是本 scaffold，「约定优于配置」的 namespace 失效协议都要求「单写者」这个前提；(2) 查询结果先进 staging、commit() 后才 put 入缓存，对应 TransactionalCach…"}],"works":[{"h":"手写 WHERE 1=1 拼接，条件全空时残留悬空 AND/OR","d":"用 StringBuilder 拼 WHERE 1=1 再逐个 append AND xxx，只要某个分支写成 OR xxx 或片段整体为空，最终 SQL 就会出现 WHERE AND status = ? 这类语法错误（复现见 ex01 的 case2 naive broken : true）。正确写法：一律用 <where>（等价…"},{"h":"<trim> 的 prefixOverrides 漏写空格导致修剪失效","d":"prefixOverrides 是按 | 分隔的前缀字符串列表，AND 末尾的空格是内容的一部分；写成 AND|OR 时 ANDname = ? 不会被剪掉。另外 TrimSqlNode 只做首尾修剪：中间多出来的 AND、中间的重复逗号（<set> 场景）它一概不管。正确写法：prefixOverrides=\"AND |OR \"（带…"},{"h":"多参数时 <if test> 里直接用属性名，取值恒为 null","d":"test 的求值对象是 MyBatis 用 ParamNameResolver 规整出的参数 Map，单参数无注解时才能裸写属性名；多参数、集合参数不带 @Param 时 OGNL 取到的是 {0: v0, 1: v1, param1: v0, ...} 这套键，写 name != null 永远不成立，条件静默丢失。正确写法：接口方…"},{"h":"${} 拼接用户输入造成 SQL 注入，且以为「只是排序」就安全","d":"${} 是宏替换：值被 String.valueOf 后拼进 SQL 文本，数据库把输入当代码重解析；ORDER BY ${col} 虽不能直接 UNION 拖库，却可用 ORDER BY (SELECT ...)/CASE WHEN 做布尔盲注与时间盲注，属于「可达但受限」的可利用面（注入对照见 ex05）。正确写法：值一律 #{}…"},{"h":"#{} 与 ${} 混用的两个反向坑","d":"其一是 ORDER BY #{sort}：#{} 变成 ? 后 MySQL 把占位符解析成常量字符串 ORDER BY 'name'，排序完全不生效却不报错，排查时极易被误判为「索引失效」；其二是 <foreach> 里写成 ${item}：DynamicSqlSource 遍历节点时同步产出文本与参数列表，${} 让文本顺序与参数顺…"},{"h":"<foreach> 集合为空拼出 IN ()","d":"<foreach> 只是把集合展开成占位符，不提供「空集合则跳过整个 IN 条件」的保护；传入 List.of() 时最终 SQL 是 ... WHERE id IN ()，MySQL 直接报 You have an error in your SQL syntax（复现见 ex02 的 empty in ok : false）。正确…"},{"h":"<foreach> 的 collection 名写错，报的是 NullPointerExce…","d":"单个 List 参数的默认键是 list、数组是 array、Map 是键名、@Param(\"ids\") 后按注解名取；名称对不上时 OGNL 取到 null，遍历处抛 BindingException/NullPointerException。正确写法：一律用 @Param(\"ids\") 显式命名并与 collection=\"ids…"},{"h":"以为一级缓存是按表失效，实际是整会话全清","d":"BaseExecutor.update() 调用的是 clearLocalCache()：CacheKey 里没有表名信息，因此同一 SqlSession 内任何一次 insert/update/delete（哪怕写的表与本次查询毫无关系）都会清空整个一级缓存；commit()/rollback()/clearCache()/flus…"}],"asks":[{"q":"一级缓存和二级缓存的作用域、失效时机分别是什么？Spring 环境下为什么常说「一级缓存的寿命等于一个事务」？","a":"一级缓存：默认开启，且没有「只开一半」的配置（localCacheScope=SESSION|STATEMENT，二选一）。 作用域是 SqlSession，CacheKey = statementId + offset + limit + SQL 文本 + 参数列表。 失效有四个触发点：会话内任意增删改（走 BaseExecutor.update() → clearLocalCache()，全会…","fu":["为什么 CacheKey 要包含 SQL 文本？动态 SQL 下命中率会怎样变化？","说说 useCache 与 flushCache 的区别与各自的默认值。"],"tag":"通用/阿里"},{"q":"MyBatis 的插件（Interceptor）是怎么工作的？分页插件为什么能改写 SQL，又为什么会在 count 查询上出错？","a":"机制：MyBatis 在四大对象创建时给它们套代理（Plugin.wrap + JDK 动态代理）， 可拦截的四处是 Executor、ParameterHandler、ResultSetHandler、StatementHandler， 通过 @Intercepts/@Signature 声明方法签名，多个插件构成责任链（InterceptorChain.pluginAll）， 执行顺序 = 配…","fu":["插件能不能拦截 Mapper 接口方法本身？为什么不行？","多个插件的执行顺序由什么决定？想在最外层生效要怎么配置？"],"tag":"通用/字节"},{"q":"延迟加载、嵌套查询与 N+1 是什么关系？什么时候该改用嵌套结果？","a":"延迟加载（lazyLoadingEnabled + fetchType=\"lazy\"）靠主对象的代理实现： 只有真正访问关联属性时才触发子查询（见 ex09，未访问时 SQL 数为 0）。 它推迟了子查询的时机，但没有减少总量——一旦后续遍历必然访问，总 SQL 数与即时加载完全相同， 这就是 N+1：1 次主查询 + N 行各 1 次子查询（ex10 实测 nestedQuery sql=6 r…","fu":["延迟加载的代理是 JDK 动态代理还是字节码增强？对实体的继承/equals 有什么影响？","嵌套结果为什么会产生重复行？重复行数由什么决定？"],"tag":"通用/美团"},{"q":"既然 ${} 有注入风险，为什么还要保留它？什么场景下不得不用，怎么才算用得安全？","a":"保留的原因：SQL 的参数（?）只能出现在语法树的叶子/值位置， 而表名、列名、ORDER BY 字段、ASC/DESC 这类结构性标识符在数据库协议层就不支持参数化 （COM_STMT_PREPARE / Parse 消息都没有「参数占位标识符」，这不止是 JDBC 的限制）。 不是不合理地留着 ${}，而是这个位置只能用宏替换。 怎么算安全：看三点——① 值是否可达外部输入？② 该位置是否允许…","fu":["MyBatis 日志里怎么快速定位哪里用了 ${}？","为什么说预编译防注入是「白名单」而转义是「黑名单」？"],"tag":"通用/阿里"}]},{"id":"spring-ch08","subj":"spring","title":"事务管理与工程实践","summary":"@Transactional 的传播行为（REQUIRED/REQUIRES_NEW/NESTED）与隔离级别；事务失效的典型场景（自调用、非 public、异常被吞、非运行时异常不回滚、多线程）；事务与 AOP 代理的关系；分层架构与 D…","concepts":[{"id":"spring-ch08/01-transactional-semantics","file":"01-transactional-semantics.md","title":"一、@Transactional 的完整语义","kind":"flow","secs":[{"h":"1. 传播行为：7 种取值与嵌套回滚的真实语义","s":"传播行为（propagation）回答的是「当前方法被调用时，事务该怎么走」。","c":{"lang":"text","code":"REQUIRED      外层回滚 -> 内层一起没了        db=[]\nREQUIRES_NEW  外层回滚 -> 内层已提交仍在      db=[insert:item]\nNESTED        内层回滚 -> 外层仍可提交        db=[insert:order]\nNESTED        外层回滚 -> 内层也一起没了      db=[]"}},{"h":"2. 隔离级别、readOnly、timeout 与回滚规则","s":"除了传播行为，@Transactional 还有四个关键属性：","c":{"lang":"text","code":"READ_UNCOMMITTED  dirty=true  nonrepeatable=true  phantom=true\nREAD_COMMITTED    dirty=false nonrepeatable=true  phantom=true\nREPEATABLE_READ   dirty=false nonrepeatable=false phantom=true\nSERIALIZABLE      dirty=false nonrepeatable=false phantom=false"}}]},{"id":"spring-ch08/02-transaction-failure-and-proxy","file":"02-transaction-failure-and-proxy.md","title":"二、事务失效的典型场景与 AOP 代理机制","kind":"compare","secs":[{"h":"1. 八类事务失效场景","s":"本机实测证据：","c":{"lang":"text","code":"失效归因两大分支\n├── 代理没生效（拦截器没跑）\n│   ├── 同类自调用：this.method()\n│   ├── 非 public 方法：代理不增强\n│   ├── 对象不是 Spring Bean（自己 new 出来的）\n│   └── 数据库引擎不支持事务（MyISAM）\n└── 代理跑了，但规则不回滚\n    ├── 异常被 catch 吞掉（方法正常返回）\n    ├── checked 异常默认不回滚\n…"}},{"h":"2. 事务与 AOP 代理：JDK 动态代理 vs CGLIB","s":"Spring 事务的底座是 TransactionInterceptor，它挂在一个代理对象上。","c":{"lang":"text","code":"调用方 --> [ 代理对象 ] --(环绕通知)--> [ 目标对象 ]\n              |                              |\n              | TransactionInterceptor:      |\n              |  begin / commit / rollback   |\n              +------------------------------+\nJDK 动态代理：要求目标实现接口，代理与被代理是「兄弟关系」（都实现同一接口）\nCGLIB 代理  ：继承目标类生成子类，代理与被代理是「父子关系」（无需接口，不能代理 final）"}}]},{"id":"spring-ch08/03-threadlocal-and-concurrency","file":"03-threadlocal-and-concurrency.md","title":"三、ThreadLocal 保存事务状态与并发陷阱","kind":"timeline","secs":[{"h":"1. ThreadLocal 与事务同步管理器","s":"ConnectionHolder 上记着 transactionActive、savepoint 等状态；commit / rollback","c":{"lang":"text","code":"TransactionSynchronizationManager（每个线程一份）\n  ThreadLocal<Map<Object, Object>> resources\n        key   = DataSource 实例\n        value = ConnectionHolder（包装了这条 Connection + 事务状态）\n\n同一线程内：Service -> Mapper 反复 getConnection()\n            都从 ThreadLocal 里拿到同一个 ConnectionHolder -> 同一条连接"}},{"h":"2. 线程池与异步下的事务丢失 / 串号","s":"本机 ex09 实测：","c":{"lang":"text","code":"单线程：上下文正确         = true\n单线程：remove() 后为空    = true\n线程池复用且不清理：串号   = true   <-- 上个任务的事务上下文被下个任务读到"}}]},{"id":"spring-ch08/04-layering-and-distributed-tx","file":"04-layering-and-distributed-tx.md","title":"四、分层架构、DTO/VO 转换与分布式事务概览","kind":"flow","secs":[{"h":"1. 分层架构与 Entity / DTO / VO 的职责边界","s":"职责口诀：转换发生在 Service 层（DTO→Entity 入库、Entity→VO 出参），","c":{"lang":"text","code":"Controller  --(DTO 入参 / VO 出参)-->  Service  --(Entity / 领域对象)-->  Mapper\n   |                                     |\n   |  参数校验、HTTP 语义                 |  事务边界（@Transactional 加在 Service）\n   +-------------------------------------+"}},{"h":"2. 多数据源与分布式事务：2PC/XA、TCC、Saga、本地消息表、Seata AT","s":"当一个业务要写两个库（或两个服务），本地事务的 ACID 就不够用了。","c":{"lang":"text","code":"phase1 all prepared (vote YES): True\ncoordinator crashed before sending COMMIT to P3\nP1 committed=True P2 committed=True P3 committed=False\nblocked participants: ['P3']\ninconsistent state: True\nrecovery: replayed decision log -> all committed: True"}}]},{"id":"spring-ch08/05-transaction-snippets","file":"05-transaction-snippets.md","title":"事务代码速查：凯喵的五段可复制片段","kind":"flow","secs":[{"h":"一、正确的最小事务方法","s":"rollbackFor = Exception.class 是关键：Spring 默认只对 RuntimeException 和 Error 回滚，受检异常（如 IOException）不会回滚，这是最高频的误解。写上它之后，任何异常都…","c":{"lang":"java","code":"@Service\npublic class OrderService {\n\n    @Transactional(rollbackFor = Exception.class)\n    public void place(Order order) {\n        orderMapper.insert(order);\n        stockMapper.decr(order.getSkuId(), order.getQty());\n    }\n}"}},{"h":"二、自调用的失效与三种修法","s":"另外两种修法：把 inner 拆到另一个 Bean（推荐，语义清楚），或者用 TransactionTemplate 手动控制。凯喵的偏好是拆 Bean——它能从结构上消除这类问题，而不是靠记住「不要自调用」。","c":{"lang":"java","code":"@Service\npublic class Svc {\n\n    @Autowired private Svc self;          // 方案一：注入自己（可能循环依赖）\n\n    public void outer() {\n        // this.inner();                  // 错了：不走代理，事务失效\n        self.inner();                     // 对了：走代理\n    }\n…"}},{"h":"三、TransactionTemplate 的显式控制","s":"需要精确控制事务边界时，模板比注解更可控。","c":{"lang":"java","code":"@Service\npublic class Svc {\n    private final TransactionTemplate tx;\n\n    public Svc(PlatformTransactionManager tm) {\n        this.tx = new TransactionTemplate(tm);\n        this.tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);\n    }\n\n…"}},{"h":"四、传播行为的四行对照","s":"凯喵的提醒：NESTED 只在支持保存点的数据源上有效（JDBC 支持，某些 JPA 实现不支持），写之前先确认。而 REQUIRES_NEW 与 REQUIRED 混用时，外层回滚不会影响内层已提交的事务——这个特性既能救命也能埋雷。","c":{"lang":"text","code":"REQUIRED      有则加入，无则新建      ← 默认，90% 场景\nREQUIRES_NEW  挂起当前，总是新建      ← 独立事务（记日志、发消息）\nNESTED        有则建保存点，无则等同 REQUIRED   ← 部分回滚\nSUPPORTS      有则加入，无则以非事务运行        ← 只读查询"}},{"h":"五、乐观锁与重试","s":"关键点是 @Retryable 必须在事务外层——如果重试发生在同一个事务里，被重试的代码读到的是同一个快照，重试多少次都一样。所以实际做法是把重试加在调用方，或者用 TransactionTemplate 让每次重试都开新事务。","c":{"lang":"java","code":"@Retryable(\n    retryFor = OptimisticLockingFailureException.class,\n    maxAttempts = 3,\n    backoff = @Backoff(delay = 50, multiplier = 2))\n@Transactional\npublic void updateBalance(Long id, BigDecimal delta) {\n    Account a = repo.findById(id).orElseThrow();\n    a.setBalance(a.getBalance().add(delta));\n    // 提交时 @Version 不匹配会抛 OptimisticLockingFailureException\n…"}},{"h":"收尾","s":"这五段代码对应事务实践里最常出错的五件事：回滚规则、自调用失效、显式事务边界、传播行为、乐观锁重试。凯喵的经验是，事务的坑几乎都能归到一句：注解只有经过代理才生效。所以任何「明明加了 @Transactional 却没回滚」的情况，第一…","c":null}]}],"exams":[{"kind":"choice","q":"REQUIRED 与 REQUIRES_NEW 的嵌套行为","stem":"外层方法标注 @Transactional（默认 REQUIRED），它调用内层方法也标注 @Transactional(propagation = REQUIRES_NEW)。内层成功提交后，外层抛出 RuntimeException。最终数据库里内层写入的数据会怎样？","opts":[{"k":"A","t":"内层数据被外层回滚一起撤销"},{"k":"B","t":"内层数据保留（它已在自己的独立事务中提交，外层回滚不影响它）"},{"k":"C","t":"内外层都提交成功"},{"k":"D","t":"取决于数据库隔离级别，无法确定"}],"ans":"B","why":"REQUIRES_NEW 会挂起外层事务并新建一个独立事务，内层提交后即持久化；外层随后回滚只撤销外层自己的改动，不会影响已提交的内层事务。参考 examples/ex03 实测输出 db after outer rollback: [insert:item]。"},{"kind":"choice","q":"@Transactional 默认回滚哪些异常","stem":"一个标注 @Transactional（未指定 rollbackFor）的方法内部抛出了 java.io.IOException（checked 异常），且该异常一路向外抛出。事务会回滚吗？","opts":[{"k":"A","t":"会回滚，任何异常都回滚"},{"k":"B","t":"不会回滚，方法已提交的部分会保留"},{"k":"C","t":"由数据库隔离级别决定"},{"k":"D","t":"只有 Error 才回滚，Exception 一律不回滚"}],"ans":"B","why":"Spring 事务默认的 rollbackFor 口径是「RuntimeException 或 Error」；checked 异常默认不触发回滚。需要 checked 异常也回滚时必须显式写 rollbackFor = Exception.class。参考 examples/ex06 实测：checked 异常回滚 = false。"},{"kind":"choice","q":"同类自调用为什么事务失效","stem":"同一个 Service 类中，public void a() 内部直接调用本类的 this.b()，而 b() 标注了 @Transactional。通过 Spring 注入的该 Service Bean 调用 a()，b() 的事务会生效吗？","opts":[{"k":"A","t":"会生效，只要方法被注解就生效"},{"k":"B","t":"不会生效，因为 this.b() 是目标对象内部的直接调用，没有经过事务代理"},{"k":"C","t":"会生效，但只在 CGLIB 代理下生效"},{"k":"D","t":"会生效，但只在 JDK 动态代理下生效"}],"ans":"B","why":"Spring 事务基于运行时代理，只有「从代理对象进入」的调用才会被拦截；this.b() 是同对象内部的直接调用，不产生新的调用边，拦截器不触发。参考 examples/ex01：自调用拦截 = false，经代理直接调用 = true。修复：拆 Bean / 自注入 / AopContext.currentProxy()。"},{"kind":"choice","q":"隔离级别与读现象","stem":"在标准 SQL 语义下，下列哪种隔离级别既能避免脏读、又能避免不可重复读，但仍可能出现幻读？","opts":[{"k":"A","t":"READ UNCOMMITTED（读未提交）"},{"k":"B","t":"READ COMMITTED（读已提交）"},{"k":"C","t":"REPEATABLE READ（可重复读）"},{"k":"D","t":"SERIALIZABLE（可串行化）"}],"ans":"C","why":"标准语义下：RU 允许三种现象；RC 允许不可重复读与幻读；RR 只允许幻读；SERIALIZABLE 三种都禁止。参考 examples/ex10 实测矩阵。注意 MySQL InnoDB 的 RR 借 next-key lock 在多数场景抑制了幻读，属数据库实现层面的加强。"},{"kind":"fix_error","q":"修正「线程池里事务上下文串号/丢失」","stem":"某 Service 在 @Transactional 方法内把写入任务提交到线程池执行，结果「主事务回滚了、子任务写入却已提交」，并且线程池复用后不同请求的事务上下文互相串号。下列改法中，哪个是根因层面的正确修法？","opts":[{"k":"A","t":"把线程池线程数调大，减少复用"},{"k":"B","t":"把需要入库的写操作留在事务线程内同步完成；副作用改用 TransactionSynchronization#afterC…"},{"k":"C","t":"把 @Transactional 加到线程池的 Runnable 上"},{"k":"D","t":"用 InheritableThreadLocal 替代 ThreadLocal"}],"ans":"B","why":"事务上下文是 ThreadLocal 绑定的，跨线程必然脱离（examples/ex09 实测：线程池复用不清理 → 串号 = true）。调大线程数只是降低复用概率，治标不治本；InheritableThreadLocal 只对新建子线程生效，对线程池复用无效；把注解加到 Runnable 上则另开事务、仍不属于主事务。根因修法是「写操作不跨线程 + 副作用放 afterCo…"},{"kind":"choice","q":"DTO / VO / Entity 的职责","stem":"关于分层架构中 DTO、VO、Entity 的职责，下列说法正确的是？","opts":[{"k":"A","t":"Entity 与表一一对应，可直接作为接口出参返回给前端"},{"k":"B","t":"DTO 用于层间传输/入参，VO 用于返回前端并做脱敏裁剪，Entity 对应数据库表；转换通常放在 Service 层"},{"k":"C","t":"VO 应该包含全部字段以便前端自由选择"},{"k":"D","t":"DTO 与 VO 是同义词，可以互相替代"}],"ans":"B","why":"Entity 对应表、可含敏感字段（password）；DTO 承接入参（只含可写字段）；VO 做脱敏裁剪后返回前端。转换放 Service 层。把 Entity 当出参会泄漏敏感字段，把 Entity 当入参会引发过度绑定与越权。参考 examples/ex14 实测：VO 不含 password 字段。"},{"kind":"coding","q":"实现支持 SAVEPOINT 的事务日志","stem":"实现一个最小事务日志 TxJournal，支持：write(x) 追加待提交写；savepoint() 记录保存点；rollback_to() 回滚到最近保存点（丢弃其后的待提交写）；commit() 把待提交写合并进 db；rollback() 丢弃全部待提交写。要求 rollback_to 为 O(k)（k 为被撤销的写数）。用下列序列验证，输出最终 db。","opts":[],"ans":"class TxJournal: def __init__(self): self.db = [] self.buf = [] self.marks = [] def write(self, x): self.buf.append(x) def savepoint(self): self.marks.append(le…","why":"保存点记录的是「待提交缓冲区当前长度」，回滚到保存点即把缓冲区截断到该长度。序列 A → savepoint → B → rollback_to（撤销 B）→ C → commit，最终 db = ['A', 'C']。这正是 NESTED 传播行为在数据库保存点上的语义（见 examples/ex04 与 ex13）。"},{"kind":"choice","q":"LeetCode 1226 The Dining Philosophers（锁顺序与死锁）","stem":"本题为 LeetCode 原题，本条目仅存元数据与链接，不搬运题面正文。它考查「多线程争用共享资源时如何避免死锁」，与数据库事务中的加锁顺序问题同源：若各事务按不同顺序申请行锁/表锁，就可能形成循环等待而死锁。下列哪种策略能从根因上避免循环等待？","opts":[{"k":"A","t":"给所有资源定义全局统一的加锁顺序（或让其中一个参与者反向加锁），打破循环等待"},{"k":"B","t":"把锁的粒度调到最小，永远不释放"},{"k":"C","t":"用忙等（自旋）替代阻塞，死锁就会消失"},{"k":"D","t":"只要 CPU 核数足够多，死锁不会发生"}],"ans":"A","why":"死锁的四个必要条件之一是「循环等待」，破坏它最直接的办法就是让所有参与者按同一全局顺序获取资源（或让其中一个反向/降级）。数据库侧同理：统一 UPDATE 的行顺序、或按主键升序批量加锁，可显著降低死锁。详见原题链接，题面不在此搬运。"}],"works":[{"h":"以为加了 @Transactional 就一定会回滚","d":"默认只对 RuntimeException 和 Error 回滚，checked 异常不回滚（ex06 实测：checked 异常回滚 = false）。正确写法：需要 checked 异常也回滚时显式声明 @Transactional(rollbackFor = Exception.class)。"},{"h":"同类方法自调用导致事务失效","d":"this.method() 不经过代理，拦截器不触发（ex01：自调用拦截 = false）。正确写法：把被调方法拆到另一个 Bean、注入自身代理，或用 @EnableAspectJAutoProxy(exposeProxy = true) + AopContext.currentProxy()。"},{"h":"把 @Transactional 加在非 public（private / package-…","d":"代理模式只增强 public 方法（ex08：package-private 方法不出现在接口上）。正确写法：事务方法必须是 public，且从代理进入。"},{"h":"异常被 catch 吞掉，方法正常返回","d":"拦截器看到「正常返回」就提交，脏数据落库（ex07 实测：吞掉后提交 = true）。正确写法：要么把异常抛出去，要么在 catch 里手动 TransactionAspectSupport.currentTransactionStatus().setRollbackOnly()。"},{"h":"跨线程/异步执行数据库操作","d":"事务上下文靠 ThreadLocal 绑定线程，new Thread / 线程池 / @Async / CompletableFuture 都拿不到（ex09 线程池串号 = true）。正确写法：写操作留在事务线程内；副作用放 TransactionSynchronization#afterCommit。"},{"h":"线程池复用不清理 ThreadLocal","d":"上一个任务的上下文被下一个任务读到（ex09 实测串号 = true），既串号也内存泄漏。正确写法：finally 里 remove()，或用 TransmittableThreadLocal 做任务级快照。"},{"h":"数据库引擎不支持事务","d":"表用 MyISAM 建，begin/commit 形同虚设。正确写法：用 InnoDB（或等价支持事务的引擎），上线前确认 SHOW TABLE STATUS 的 Engine。"},{"h":"REQUIRES_NEW 在高并发下打死连接池","d":"它每次都新开一条连接（挂起外层）。正确写法：评估连接池大小与并发量；能用 REQUIRED 就用 REQUIRED，REQUIRES_NEW 只用于确实要独立提交的场景（如审计日志）。"}],"asks":[{"q":"@Transactional 在哪些情况下会失效？","a":"分两大分支回答最清晰： 一、代理没生效（拦截器根本没跑） 1. 同类自调用 this.method()——不经过代理（examples/ex01 实测拦截 = false）； 2. 非 public（private/package-private）方法——代理不增强（examples/ex08）； 3. 对象不是 Spring 管理的 Bean（自己 new 的，或未被扫描）； 4. 数据库引擎不…","fu":["为什么同类自调用会失效？底层是什么机制？","AopContext.currentProxy() 需要什么前提配置？"],"tag":"通用/阿里"},{"q":"REQUIRED、REQUIRES_NEW、NESTED 有什么区别？内层回滚，外层会怎样？","a":"REQUIRED（默认）：有外层就加入，内外共用一个事务；内层异常把整个事务标记 rollback-only，最终一起回滚。 - REQUIRES_NEW：挂起外层、新开独立事务（新连接）；内层提交后外层回滚不影响内层（examples/ex03 实测 db 保留 insert:item）。 - NESTED：在外层事务内建保存点（同一条连接）；内层回滚只回退到保存点，外层仍可提交（example…","fu":["NESTED 底层靠什么实现？依赖数据库什么能力？","REQUIRES_NEW 在高并发下有什么风险？"],"tag":"通用/腾讯"},{"q":"为什么 @Transactional 默认只对 RuntimeException 回滚？checked 异常怎么办？","a":"默认口径来自 TransactionAspectSupport#rollbackOn(Throwable)：只对 RuntimeException 与 Error 返回 true；checked 异常默认不回滚（examples/ex06 实测 = false）。 设计动机：Spring 认为「未受检异常」代表不可预期的系统错误，应当回滚；而 checked 异常是可预期的业务分支，交回开发者自行…","fu":["如果 checked 异常被 catch 后没抛出，事务会回滚吗？","rollbackFor 写 Exception 和写 Throwable 有区别吗？"],"tag":"通用/百度"},{"q":"Spring 的隔离级别和数据库隔离级别是什么关系？MySQL REPEATABLE READ 下还会有幻读吗？","a":"Spring 的 Isolation 枚举只是对 JDBC Connection.TRANSACTION_ 常量的封装，最终由数据库实现语义；Isolation.DEFAULT 表示用数据库默认值（MySQL 默认 REPEATABLE READ，Oracle 默认 READ COMMITTED）。 标准 SQL 语义下（examples/ex10 实测矩阵）：RU 三种现象都可能；RC 可能不可…","fu":["InnoDB 是怎么用 next-key lock 抑制幻读的？","什么时候应该显式把隔离级别调到 READ COMMITTED？"],"tag":"通用/阿里"}]}];

